                last_exc = exc
                await asyncio.sleep(0.1)
        raise RuntimeError(f"cannot connect to astrag-core: {last_exc}")

    def send(self, *fields):
        data = ("\t".join(_core_field(f) for f in fields) + "\n").encode()
        if self.writer is None:
            self.pending.append(data)
        else:
            self.writer.write(data)

    def _core_gone(self, what: str):
        for _ in range(20):
            if self.proc.poll() is not None:
                break
            time.sleep(0.05)
        rc = self.proc.poll()
        if rc in (0, -signal.SIGTERM, -signal.SIGINT):
            os._exit(0)
        os._exit(1)

    async def _watchdog(self):
        while True:
            await asyncio.sleep(1.0)
            if self.proc.poll() is not None:
                self._core_gone("exited")

    async def _reader(self, reader):
        while True:
            line = await reader.readline()
            if not line:
                self._core_gone("control connection closed")
            try:
                self._handle(line.decode("utf-8", "replace").rstrip("\n").split("\t"))
            except Exception:
                pass

    def _handle(self, f):
        if f[0] == "STAT" and len(f) >= 15:
            pids = []
            for item in filter(None, f[11].split(",")):
                p, k, st = item.split(":")
                pids.append((int(p), int(k), int(st)))
            pmts = []
            for item in filter(None, f[12].split(",")):
                p, pnr = item.split(":")
                pmts.append((int(p), int(pnr)))
            a_map = {0x0F: "AAC", 0x11: "AAC-LATM", 0x81: "AC3", 0x06: "AC3", 0x87: "EAC3", 0x03: "MP2", 0x04: "MP2"}
            audio_tracks = []
            if len(f) >= 16 and f[15]:
                for item in filter(None, f[15].split(",")):
                    parts_a = item.split(":")
                    if len(parts_a) >= 3:
                        a_idx = int(parts_a[0])
                        a_pid = int(parts_a[1])
                        a_st = int(parts_a[2])
                        a_lang = parts_a[3] if len(parts_a) >= 4 else ""
                        audio_tracks.append({
                            "index": a_idx,
                            "pid": a_pid,
                            "codec": a_map.get(a_st, "AUDIO"),
                            "lang": a_lang,
                        })
            if not audio_tracks:
                for a_pid, k, a_st in pids:
                    if k == 2:
                        audio_tracks.append({
                            "index": len(audio_tracks),
                            "pid": a_pid,
                            "codec": a_map.get(a_st, "AUDIO"),
                            "lang": "",
                        })
            self.stats[f[1]] = {
                "onair": f[2] == "1", "bitrate": float(f[3]), "cc_errors": int(f[4]), "pes_errors": int(f[5]),
                "scrambled": f[6] == "1", "input_id": int(f[7]), "packets": int(f[8]), "pcr_pid": int(f[9]),
                "tsid": int(f[10]), "pids": pids, "pmts": pmts, "input_errors": int(f[13]),
                "last_error": f[14] or None, "audio_tracks": audio_tracks, "updated": time.monotonic(),
            }
        elif f[0] == "SESS+" and len(f) >= 6:
            core_id = int(f[1])
            skey = f"core:{core_id}"
            self.sess_map[core_id] = skey
            if "MANAGER" in globals():
                sess = PlaySession(skey, f[2], f[3] or "127.0.0.1", "MPEG-TS", f[5] or "Player")
                sess.core_id = core_id
                MANAGER.sessions[skey] = sess
                w = MANAGER.workers.get(f[2])
                if w:
                    w.touch_client()
        elif f[0] == "SESS-" and len(f) >= 2:
            skey = self.sess_map.pop(int(f[1]), None)
            if skey is not None and "MANAGER" in globals():
                MANAGER.sessions.pop(skey, None)


CORE: Optional[CoreSupervisor] = None


def _via_core(req: web.Request) -> bool:
    return CORE is not None and req.headers.get("x-astrag-via") == CORE.secret


def _client_ip(req: web.Request) -> str:
    if _via_core(req):
        xff = req.headers.get("X-Forwarded-For", "").strip()
        if xff:
            return xff.split(",")[0].strip()
    return req.remote or "127.0.0.1"


def _core_eligible(config: dict) -> bool:
    if CORE is None:
        return False
    for url in config.get("input", []):
        if urlsplit(url.split("#", 1)[0]).scheme.lower() not in ("http", "https"):
            return False
    for url in config.get("output", []):
        if urlsplit(url.split("#", 1)[0]).scheme.lower() not in ("http", "https"):
            return False
    return True


class CoreEngine:
    """Engine facade for channels served by astrag-core."""

    def __init__(self, config: dict, seg_dur: float, max_segs: int):
        self.config = config
        self.sid = config["id"]
        self.seg_dur = seg_dur
        self.max_segs = max_segs
        self._running = False
        self._started = time.monotonic()

    def start(self):
        if CORE is not None:
            CORE.stats.pop(self.sid, None)
            CORE.send("ADD", self.sid, f"{self.seg_dur:.3f}", self.max_segs, self.config.get("name", ""),
                      *self.config["input"])
        self._running = True
        self._started = time.monotonic()
        return self

    def stop(self):
        if self._running and CORE is not None:
            CORE.send("DEL", self.sid)
        self._running = False
        if CORE is not None:
            CORE.stats.pop(self.sid, None)

    def unsubscribe(self, queue):
        return None

    def stats(self, include_pids: bool = True):
        st = CORE.stats.get(self.sid, {}) if CORE is not None else {}
        br = st.get("bitrate", 0.0)
        out = {
            "running": self._running, "bitrate": br, "effective_bitrate": br, "average_bitrate": br,
            "continuity_errors": st.get("cc_errors", 0), "cc_errors": st.get("cc_errors", 0),
            "pes_errors": st.get("pes_errors", 0), "scrambled": st.get("scrambled", False),
            "input_id": st.get("input_id", 1), "packets": st.get("packets", 0),
            "bytes": st.get("packets", 0) * 188, "input_errors": st.get("input_errors", 0),
            "last_error": st.get("last_error"), "elapsed": time.monotonic() - self._started,
        }
        if include_pids:
            out["pids"] = {str(p): {"type": {1: "VIDEO", 2: "AUDIO"}.get(k, "DATA"), "stream_type": t}
                           for p, k, t in st.get("pids", [])}
        return out


def _start_core(host: str, port: int):
    """Launch astrag-core on the public port; returns (CoreSupervisor, internal_port) or (None, None)."""
    core_bin = Path(os.environ.get("ASTRA_CORE_BIN") or (APP_DIR / "astrag-core"))
    core_src = APP_DIR / "astrag_core.c"
    if core_src.is_file() and (not core_bin.is_file() or core_src.stat().st_mtime > core_bin.stat().st_mtime):
        try:
            subprocess.run(
                ["gcc", "-O2", "-s", "-o", str(core_bin), str(core_src), "-lssl", "-lcrypto", "-lpthread", "-lm"],
                timeout=30,
                check=False,
            )
            if core_bin.is_file():
                os.chmod(core_bin, 0o755)
        except Exception:
            pass
    if os.environ.get("ASTRA_CORE", "1") == "0" or not core_bin.is_file() or not os.access(core_bin, os.X_OK):
        return None, None
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        internal = s.getsockname()[1]
    secret = secrets.token_hex(16)
    ctl = f"astrag-core-{os.getpid()}-{secrets.token_hex(4)}"

    def _set_pdeathsig():
        try:
            ctypes.CDLL("libc.so.6").prctl(1, signal.SIGTERM)
        except Exception:
            pass

    try:
        proc = subprocess.Popen(
            [str(core_bin), "--ctl", ctl, "--secret", secret, "--upstream", str(internal), "--listen", f"{host}:{port}"],
            stdin=subprocess.DEVNULL,
            preexec_fn=_set_pdeathsig,
        )
    except OSError:
        return None, None
    atexit.register(lambda: proc.terminate() if proc.poll() is None else None)
    time.sleep(0.4)
    if proc.poll() is not None:
        return None, None
    return CoreSupervisor(proc, ctl, secret, host), internal


def _core_handoff(req: web.Request, *fields) -> web.Response:
    """Tell astrag-core (which relayed this request) to serve the media itself."""
    directive = "|".join(quote(str(f), safe="") for f in fields)
    return web.Response(body=b"", headers={"X-Astrag-Core": directive})


def normalize_input_url(raw_url: str) -> str:
    u = raw_url.strip()
    if u.startswith("hlss://"):
        return "https://" + u[7:]
    if u.startswith("hls://"):
        return "http://" + u[6:]
    if u.startswith("tshttps://"):
        return "https://" + u[10:]
    if u.startswith("tshttp://"):
        return "http://" + u[9:]
    if u.startswith(("m4fs://", "m4ss://")):
        rest = u.split("://", 1)[1].rstrip("/")
        return f"https://{rest}/mpegts" if not rest.endswith(("/mpegts", ".m3u8")) else f"https://{rest}"
    if u.startswith(("m4f://", "m4s://")):
        rest = u.split("://", 1)[1].rstrip("/")
        return f"http://{rest}/mpegts" if not rest.endswith(("/mpegts", ".m3u8")) else f"http://{rest}"
    if u.startswith(("dashs://", "mpds://")):
        return "https://" + u.split("://", 1)[1]
    if u.startswith(("dash://", "mpd://")):
        return "http://" + u.split("://", 1)[1]
    return u


_LAT_TO_CYR_HOMOGLYPHS = str.maketrans({
    "a": "а", "b": "в", "c": "с", "e": "е", "h": "н",
    "k": "к", "m": "м", "o": "о", "p": "р", "t": "т",
    "x": "х", "y": "у",
})


def _normalize_channel_match_key(raw: str) -> str:
    """Case-insensitive and font-insensitive channel name normalizer (e.g. 'Боец', 'боец', 'БОЕЦ', '𝐁𝐨𝐞𝐜')."""
    if not raw:
        return ""
    s = unicodedata.normalize("NFKC", str(raw)).casefold().replace("ё", "е")
    s = re.sub(r"[^0-9a-zа-я]+", "", s)
    if not s:
        return ""
    if re.search(r"[а-я]", s):
        s = s.translate(_LAT_TO_CYR_HOMOGLYPHS)
    return s


def _rewrite_remote_url_host(raw_url: str, rhost: str) -> str:
    """Rewrite loopback/wildcard hostnames in remote HTTP/HTTPS stream URLs to the remote node IP.
    Non-HTTP schemes (e.g. dvb://, udp://, rtp://, srt://, file://) are local to the remote server and return empty string."""
    u = str(raw_url or "").strip()
    if not u or not rhost:
        return ""
    base, *frag = u.split("#", 1)
    suffix = f"#{frag[0]}" if frag else ""
    try:
        sp = urlsplit(base.strip())
    except Exception:
        return ""
    scheme = (sp.scheme or "").lower()
    if scheme not in ("http", "https", "hls", "hlss", "tshttp", "tshttps"):
        return ""
    host = (sp.hostname or "").strip().lower()
    if host in ("", "0", "0.0.0.0", "127.0.0.1", "localhost", "::1"):
        port_part = f":{sp.port}" if sp.port else ""
        auth_part = ""
        if sp.username is not None:
            auth_part = sp.username
            if sp.password is not None:
                auth_part += f":{sp.password}"
            auth_part += "@"
        path = sp.path or "/"
        q = f"?{sp.query}" if sp.query else ""
        return f"{scheme}://{auth_part}{rhost}{port_part}{path}{q}{suffix}"
    return base.strip() + suffix


def _build_cluster_stream_inputs(
    rs: dict,
    rhost: str,
    rport: int = 8000,
    play_port: Optional[int] = None,
    rlogin: str = "",
    rpass: str = "",
    play_auth: str = "",
    ruser: str = "",
    srv_type: str = "auto",
    remote_cfg: Optional[dict] = None,
) -> List[str]:
    """Build ordered failover inputs for a remote cluster stream (matching astron/astrag_backend.py & Astra Cesbo):
    1) Direct stream from the remote node (/play/<id> with ?token=... resolved from remote_cfg['users'] or stream token)
    2) External HTTP/HTTPS output links of the remote channel (with 0/127.0.0.1/0.0.0.0 rewritten to rhost)
    3) Original HTTP/HTTPS input links of the remote channel as deep fallback (local dvb://, udp://, srt:// are ignored)
    """
    orig_id = str(rs.get("id") or rs.get("name") or "").strip()
    rhost = str(rhost or "").strip()
    user = (rlogin or ruser or "").strip()
    rcfg = remote_cfg if isinstance(remote_cfg, dict) else {}
    rsettings = rcfg.get("settings") if isinstance(rcfg.get("settings"), dict) else {}
    rauth = rcfg.get("auth") if isinstance(rcfg.get("auth"), dict) else {}
    rusers = rcfg.get("users") if isinstance(rcfg.get("users"), dict) else {}

    play_token = ""
    if rauth.get("enable") or rsettings.get("http_play_users") or rusers:
        if user and isinstance(rusers.get(user), dict) and rusers[user].get("token"):
            play_token = str(rusers[user]["token"]).strip()
        else:
            for uinfo in rusers.values():
                if isinstance(uinfo, dict) and uinfo.get("enable", True) not in (False, 0, "0", "false") and uinfo.get("token"):
                    play_token = str(uinfo["token"]).strip()
                    break
    if not play_token:
        play_token = str(rs.get("http_play_token") or rs.get("token") or "").strip()

    p_port = int(rsettings.get("http_play_port") or play_port or rcfg.get("http_port") or rport or 8000)

    q_suffix = play_auth
    if not q_suffix:
        if play_token:
            q_suffix = f"?token={play_token}"
        elif bool(rs.get("http_play_users")) and user:
            q_suffix = f"?auth={user}:{rpass}" if rpass else f"?auth={user}"

    play_url = ""
    if orig_id and rhost and p_port:
        if str(srv_type or "").lower() == "flussonic":
            play_url = f"http://{rhost}:{p_port}/{orig_id}/mpegts{q_suffix}"
        else:
            play_url = f"http://{rhost}:{p_port}/play/{orig_id}{q_suffix}"

    out_urls: List[str] = []
    if rs.get("direct_url"):
        rw_d = _rewrite_remote_url_host(str(rs["direct_url"]), rhost)
        if rw_d and rw_d not in out_urls:
            out_urls.append(rw_d)
    raw_outputs = rs.get("output") or []
    if isinstance(raw_outputs, str):
        raw_outputs = [raw_outputs]
    if isinstance(raw_outputs, list):
        for out_u in raw_outputs:
            if isinstance(out_u, str):
                rw = _rewrite_remote_url_host(out_u, rhost)
                if rw and rw not in out_urls:
                    out_urls.append(rw)

    in_urls: List[str] = []
    raw_inputs = rs.get("input") or rs.get("inputs") or []
    if isinstance(raw_inputs, str):
        raw_inputs = [raw_inputs]
    if isinstance(raw_inputs, list):
        for in_u in raw_inputs:
            if isinstance(in_u, str):
                rw = _rewrite_remote_url_host(in_u, rhost)
                if rw and rw not in in_urls:
                    in_urls.append(rw)

    candidates: List[str] = []
    http_play_enabled = bool(rsettings.get("http_play_stream") or rsettings.get("http_play_hls") or not rsettings)
    ordered = [play_url, *out_urls, *in_urls] if http_play_enabled else [*out_urls, play_url, *in_urls]
    for u in ordered:
        if u and u not in candidates:
            candidates.append(u)

    return candidates



def generate_flustream_conf(data: dict) -> str:
    lines = [
        "# Global StreamFlow Aria Configuration",
        f"http {data.get('http_port', 8080)};",
        f"edit_auth {data.get('admin_user', 'admin')} {data.get('admin_pass', 'admin')};",
        f"dvr_root {data.get('dvr_root', '/var/lib/flustream/dvr')} {data.get('dvr_disk_limit', 85)}%;",
    ]
    if data.get("global_auth_url"):
        lines.append(f"auth_backend {data['global_auth_url']};")
    if data.get("cluster_key"):
        lines.append(f"cluster_key {data['cluster_key']};")
    for peer in data.get("peers", []):
        if peer.strip():
            lines.append(f"peer {peer.strip()};")
    for srv in data.get("servers", []):
        if isinstance(srv, dict) and srv.get("host"):
            srv_b64 = base64.b64encode(json.dumps(srv, ensure_ascii=False).encode("utf-8")).decode("ascii")
            lines.append(f"cluster_server {srv_b64};")
    for src in data.get("cluster_sources", []):
        host = src.get("host", "").strip()
        if not host:
            continue
        lines.append(f"source {host} {{")
        if src.get("proto"):
            lines.append(f"  proto {src['proto']};")
        if src.get("only"):
            lines.append(f"  only {src['only']};")
        if src.get("except"):
            lines.append(f"  except {src['except']};")
        lines.append("}")
    lines.append("")

    for s in data.get("streams", []):
        if s.get("_cluster_host"):
            continue
        directive = "ondemand" if s.get("mode") == "ondemand" else "stream"
        lines.append(f"{directive} {s['name']} {{")
        if s.get("title"):
            lines.append(f"  title \"{s['title']}\";")
        auto_in = set(s.get("_cluster_auto_inputs") or [])
        for inp in s.get("inputs", []):
            if inp.strip() and inp.strip() not in auto_in:
                lines.append(f"  input {inp.strip()};")
        lines.append(f"  source_timeout {s.get('source_timeout', 30)};")
        lines.append(f"  buffer_mode {s.get('buffer_mode', '30s')};")
        lines.append(f"  quality {s.get('quality', 'best')};")
        lines.append(f"  engine {s.get('engine', 'ffmpeg')};")
        lines.append(f"  audio_track {s.get('audio_track', '0')};")
        if s.get("user_agent"):
            lines.append(f"  user_agent \"{s['user_agent']}\";")
        if s.get("mode") == "ondemand":
            lines.append(f"  clients_timeout {s.get('clients_timeout', 45)};")
        if int(s.get("dvr_hours", 0)) > 0:
            lines.append(f"  dvr {DVR_ROOT} {int(s['dvr_hours'])}h;")
        for p in s.get("pushes", []):
            if p.strip():
                lines.append(f"  push {p.strip()};")
        if s.get("token"):
            lines.append(f"  token {s['token']};")
        if s.get("on_play"):
            lines.append(f"  on_play {s['on_play']};")
        if not s.get("enabled", True):
            lines.append("  disabled;")
        lines.append("}")
        lines.append("")
    return "\n".join(lines)


def parse_flustream_conf(text: str, current_data: dict) -> dict:
    data = {
        "http_port": current_data.get("http_port", 8080),
        "admin_user": current_data.get("admin_user", "admin"),
        "admin_pass": current_data.get("admin_pass", "admin"),
        "ui_theme": current_data.get("ui_theme", "2"),
        "ui_lang": current_data.get("ui_lang", "ru"),
        "dvr_root": current_data.get("dvr_root", "/var/lib/flustream/dvr"),
        "dvr_disk_limit": current_data.get("dvr_disk_limit", 85),
        "global_auth_url": "",
        "cluster_key": current_data.get("cluster_key", "flustream_secret"),
        "peers": [],
        "servers": [],
        "cluster_sources": [],
        "streams": []
    }
    m_port = re.search(r"^\s*http\s+(\d+)\s*;", text, re.M)
    if m_port:
        data["http_port"] = int(m_port.group(1))
    m_eauth = re.search(r"^\s*edit_auth\s+(\S+)\s+(\S+)\s*;", text, re.M)
    if m_eauth:
        data["admin_user"] = m_eauth.group(1)
        data["admin_pass"] = m_eauth.group(2)
    m_dvr = re.search(r"^\s*dvr_root\s+(\S+)\s+(\d+)%\s*;", text, re.M)
    if m_dvr:
        data["dvr_root"] = m_dvr.group(1)
        data["dvr_disk_limit"] = int(m_dvr.group(2))
    m_auth = re.search(r"^\s*auth_backend\s+(\S+)\s*;", text, re.M)
    if m_auth:
        data["global_auth_url"] = m_auth.group(1)
    m_ckey = re.search(r"^\s*cluster_key\s+(\S+)\s*;", text, re.M)
    if m_ckey:
        data["cluster_key"] = m_ckey.group(1)
    for m_peer in re.finditer(r"^\s*peer\s+([^;{]+)", text, re.M):
        data["peers"].append(m_peer.group(1).strip())
    for m_csrv in re.finditer(r"^\s*cluster_server\s+(\S+)\s*;", text, re.M):
        try:
            srv_obj = json.loads(base64.b64decode(m_csrv.group(1).strip()).decode("utf-8"))
            if isinstance(srv_obj, dict) and srv_obj.get("host"):
                data["servers"].append(srv_obj)
        except Exception:
            pass
    if not data["servers"] and current_data.get("servers"):
        data["servers"] = list(current_data.get("servers", []))
    for m_src in re.finditer(r"source\s+(\S+)\s*\{([^}]*)\}", text, re.S):
        shost, sbody = m_src.group(1).strip(), m_src.group(2)
        src_obj = {"host": shost, "proto": "hls", "only": "", "except": ""}
        for sline in sbody.splitlines():
            sl = sline.strip().rstrip(";")
            if sl.startswith("only "):
                src_obj["only"] = sl.split(" ", 1)[1].strip()
            elif sl.startswith("except "):
                src_obj["except"] = sl.split(" ", 1)[1].strip()
            elif sl.startswith("proto "):
                src_obj["proto"] = sl.split(" ", 1)[1].strip()
        data["cluster_sources"].append(src_obj)

    block_re = re.compile(r"(stream|ondemand)\s+([a-zA-Z0-9_\-]+)\s*\{([^}]*)\}", re.S)
    for match in block_re.finditer(text):
        mode, name, body = match.group(1), match.group(2), match.group(3)
        st = {
            "name": name,
            "title": name,
            "mode": mode,
            "quality": "best",
            "engine": "ffmpeg",
            "audio_track": "0",
            "buffer_mode": "30s",
            "user_agent": "",
            "enabled": True,
            "inputs": [],
            "source_timeout": 30,
            "clients_timeout": 45,
            "dvr_hours": 0,
            "pushes": [],
            "token": "",
            "on_play": ""
        }
        for raw_line in body.splitlines():
            line = raw_line.strip().rstrip(";")
            if not line or line.startswith("#"):
                continue
            if line.startswith("buffer_mode "): st["buffer_mode"] = line.split(" ", 1)[1].strip()
            elif line.startswith("title "):
                st["title"] = line.split(" ", 1)[1].strip('"\'')
            elif line.startswith("input "):
                st["inputs"].append(line.split(" ", 1)[1].strip())
            elif line.startswith("quality "): st["quality"] = line.split(" ", 1)[1].strip()
            elif line.startswith("engine "): st["engine"] = line.split(" ", 1)[1].strip()
            elif line.startswith("audio_track "): st["audio_track"] = line.split(" ", 1)[1].strip()
            elif line.startswith("user_agent "): st["user_agent"] = line.split(" ", 1)[1].strip('"\'')
            elif line.startswith("source_timeout "):
                st["source_timeout"] = int(line.split(" ", 1)[1].strip())
            elif line.startswith("clients_timeout "):
                st["clients_timeout"] = int(line.split(" ", 1)[1].strip())
            elif line.startswith("dvr "):
                for p in line.split()[1:]:
                    if p.endswith("h"):
                        st["dvr_hours"] = int(p[:-1])
                    elif p.endswith("d"):
                        st["dvr_hours"] = int(p[:-1]) * 24
            elif line.startswith("push "):
                st["pushes"].append(line.split(" ", 1)[1].strip())
            elif line.startswith("token "):
                st["token"] = line.split(" ", 1)[1].strip()
            elif line.startswith("on_play "):
                st["on_play"] = line.split(" ", 1)[1].strip()
            elif line == "disabled":
                st["enabled"] = False
        data["streams"].append(st)
    return data


class PlaySession:
    def __init__(self, session_id: str, stream_name: str, ip: str, proto: str, user_agent: str):
        self.id = session_id
        self.stream_name = stream_name
        self.ip = ip
        self.proto = proto
        self.user_agent = user_agent[:80]
        self.started_at = time.time()
        self.last_seen = time.time()
        self.bytes_sent = 0
        self.kicked = False
        self.core_id: Optional[int] = None

    def to_dict(self):
        dur = max(1, int(time.time() - self.started_at))
        return {
            "id": self.id,
            "stream": self.stream_name,
            "ip": self.ip,
            "proto": self.proto,
            "user_agent": self.user_agent,
            "duration": dur,
            "bytes_sent": self.bytes_sent,
            "mbits": round((self.bytes_sent * 8) / dur / 1_000_000, 3)
        }


class StreamWorker:
    def __init__(self, cfg: dict, manager: "StreamManager"):
        self.cfg = cfg
        self.manager = manager
        self.name = cfg["name"]
        self.ram_dir = RAM_ROOT / self.name
        self.dvr_dir = DVR_ROOT / self.name
        self.proc: Optional[asyncio.subprocess.Process] = None
        self.astrag_engine: Optional[Union[AstraGEngine, CoreEngine]] = None
        self.engine_error: bool = False
        self._last_astrag_pkts: int = 0
        self._last_astrag_pkt_ts: float = 0.0
        self.dash_proc: Optional[asyncio.subprocess.Process] = None
        self.last_dash_req: float = 0.0
        self.push_procs: Dict[str, asyncio.subprocess.Process] = {}
        self.active_input_idx = 0
        self.status = "Disabled"
        self.started_at: Optional[float] = None
        self.last_segment_time: float = time.time()
        self.last_client_time: float = time.time()
        self.bitrate_in_kbps: float = 0.0
        self.cached_buffer_sec: int = 0
        self.codec_info: str = "Pass-through (-c copy)"
        self.detected_audio_tracks: List[dict] = []
        self._probed_video_res: str = ""
        self._last_synced_seq: int = -1
        self.probed_once: bool = False
        self.processed_segments: set = set()
        self.stop_event = asyncio.Event()
        self.task: Optional[asyncio.Task] = None
        self._kbps_samples: List[float] = []
        self._last_upper_probe_ts: float = 0.0
        self._probing_upper: bool = False

    def start(self):
        self.stop_event.clear()
        self.task = asyncio.create_task(self._lifecycle_loop())

    async def stop(self):
        self.stop_event.set()
        await self._kill_ffmpeg()
        if self.task:
            self.task.cancel()
            try:
                await self.task
            except asyncio.CancelledError:
                pass
        self.status = "Disabled"
        self.engine_error = False

    def touch_client(self):
        self.last_client_time = time.time()

    def active_clients_count(self) -> int:
        return self.manager.active_clients_map.get(self.name, 0)

    def running_pushes_count(self) -> int:
        return sum(1 for p in self.push_procs.values() if p.returncode is None)

    def target_buffer_seconds(self) -> int:
        return 6 if self.cfg.get("buffer_mode") == "normal" else 30

    def buffered_seconds(self) -> int:
        return self.cached_buffer_sec if self.status == "Online" else 0

    async def _kill_ffmpeg(self):
        for p in list(self.push_procs.values()):
            if p.returncode is None:
                try:
                    p.kill()
                except Exception:
                    pass
        self.push_procs.clear()
        if self.astrag_engine is not None:
            try:
                res = self.astrag_engine.stop()
                if asyncio.iscoroutine(res):
                    await res
            except Exception:
                pass
            self.astrag_engine = None
        if self.proc and self.proc.returncode is None:
            try:
                self.proc.terminate()
                await asyncio.wait_for(self.proc.wait(), timeout=2.0)
            except Exception:
                try:
                    self.proc.kill()
                except Exception:
                    pass
        self.proc = None
        self.bitrate_in_kbps = 0.0
        self.cached_buffer_sec = 0
        self._kbps_samples.clear()
        self._last_astrag_pkts = 0
        self._last_astrag_pkt_ts = 0.0
        self._last_synced_seq = -1

    async def _resolve_best_variant_url(self, raw_url: str) -> str:
        input_url = normalize_input_url(raw_url)
        pref = str(self.cfg.get("quality", "best")).lower()
        if not input_url.startswith(("http://", "https://")) or not self.manager.http_client:
            return raw_url
        low_u = input_url.lower().split("?", 1)[0]
        # Пропускаем только заведомо прямые MPEG-TS потоки (/play/..., .ts, /mpegts) или уже проверенные не-HLS ссылки
        if (
            raw_url in self.manager.non_hls_urls
            or low_u.endswith((".ts", "/mpegts", ".mp4", ".mkv", ".flv"))
            or "/play/" in low_u
            or raw_url.lower().startswith(("tshttp://", "tshttps://", "m4f://", "m4fs://", "m4s://", "m4ss://"))
        ):
            return raw_url
        try:
            headers = {
                "User-Agent": (self.cfg.get("user_agent") or "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")
            }
            async with self.manager.http_client.get(input_url, headers=headers, ssl=False, timeout=ClientTimeout(total=4)) as resp:
                if resp.status != 200:
                    return raw_url
                ct = resp.headers.get("Content-Type", "").lower()
                if "video/mp2t" in ct or "octet-stream" in ct:
                    self.manager.non_hls_urls.add(raw_url)
                    return raw_url
                raw_chunk = await resp.content.read(16384)
                if not raw_chunk.lstrip().startswith(b"#EXTM3U"):
                    self.manager.non_hls_urls.add(raw_url)
                    return raw_url
                self.manager.hls_urls.add(raw_url)
                self.manager.hls_urls.add(input_url)
                text = raw_chunk.decode("utf-8", errors="ignore")
                final_base_url = str(resp.url)
                if final_base_url:
                    self.manager.hls_urls.add(final_base_url)
        except Exception:
            return raw_url

        if "#EXT-X-STREAM-INF" not in text:
            return final_base_url or input_url

        variants = []
        lines = [l.strip() for l in text.splitlines() if l.strip()]
        i = 0
        while i < len(lines):
            line = lines[i]
            if line.startswith("#EXT-X-STREAM-INF"):
                bw = 0
                width = 0
                height = 0
                m_bw = re.search(r"AVERAGE-BANDWIDTH=(\d+)", line) or re.search(r"(?:^|,)BANDWIDTH=(\d+)", line)
                if m_bw:
                    bw = int(m_bw.group(1))
                m_res = re.search(r"RESOLUTION=(\d+)x(\d+)", line)
                if m_res:
                    width = int(m_res.group(1))
                    height = int(m_res.group(2))
                j = i + 1
                while j < len(lines) and lines[j].startswith("#"):
                    j += 1
                if j < len(lines):
                    v_url = urljoin(final_base_url, lines[j])
                    if "audio-only=true" not in v_url.lower():
                        if not height:
                            m_uh = re.search(r"(?:^|[^0-9])(2160|1440|1080|720|576|540|480|360|288|240)p", v_url.lower())
                            if m_uh:
                                height = int(m_uh.group(1))
                                width = int(round(height * 16 / 9))
                        variants.append({"bw": bw, "width": width, "height": height, "url": v_url})
                i = j
            i += 1

        if not variants:
            return final_base_url or raw_url

        variants.sort(key=lambda x: (x["height"], x["width"], x["bw"]))
        if pref == "low":
            chosen = variants[0]
        elif pref in ("1080", "1080p"):
            cands = [v for v in variants if v["height"] and v["height"] <= 1080]
            chosen = cands[-1] if cands else variants[-1]
        elif pref in ("720", "720p"):
            cands = [v for v in variants if v["height"] and v["height"] <= 720]
            chosen = cands[-1] if cands else variants[0]
        elif pref in ("480", "480p", "360", "360p"):
            cands = [v for v in variants if v["height"] and v["height"] <= 540]
            chosen = cands[-1] if cands else variants[0]
        else:
            chosen = variants[-1]
        self.manager.hls_urls.add(chosen["url"])
        return chosen["url"]

    def _build_primary_hls_cmd(self, raw_input_url: str) -> List[str]:
        input_url = normalize_input_url(raw_input_url)
        self.ram_dir.mkdir(parents=True, exist_ok=True)
        cmd = [
            "ffmpeg", "-nostdin", "-y", "-hide_banner", "-loglevel", "error",
            "-threads", "1", "-probesize", "5000000", "-analyzeduration", "5000000",
            "-fflags", "+genpts+discardcorrupt+igndts"
        ]
        if input_url.startswith("rtsp://"):
            cmd += ["-rtsp_transport", "tcp"]
        elif input_url.startswith(("http://", "https://")):
            cmd += [
                "-rw_timeout", "15000000",
                "-user_agent", (self.cfg.get("user_agent") or "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"),
                "-reconnect", "1",
                "-reconnect_at_eof", "1",
                "-reconnect_streamed", "1",
                "-reconnect_delay_max", "5"
            ]
            low_in = input_url.lower().split("?", 1)[0]
            if (raw_input_url in self.manager.hls_urls or input_url in self.manager.hls_urls or low_in.endswith((".m3u8", ".m3u"))) and not low_in.endswith(".ts"):
                cmd += ["-f", "hls", "-live_start_index", "-2"]
        elif input_url.startswith("udp://"):
            cmd += ["-timeout", str(int(self.cfg.get("source_timeout", 15)) * 1_000_000)]
        elif raw_input_url.strip().startswith("srt://"):
            u_srt = raw_input_url.strip()
            # Если указан наш собственный сервер 62.60.250.90 или 0.0.0.0 без mode=caller — слушаем порт как сервер (listener)
            if "mode=listener" in u_srt or u_srt.startswith(("srt://0.0.0.0:", "srt://127.0.0.1:", "srt://62.60.250.90:")) and "mode=caller" not in u_srt:
                port_m = re.search(r":(\d+)", u_srt)
                p_num = port_m.group(1) if port_m else "54333"
                input_url = f"srt://0.0.0.0:{p_num}?mode=listener&timeout=15000000&latency=200000"
            else:
                input_url = u_srt if "?" in u_srt else f"{u_srt}?mode=caller&timeout=8000000&latency=200000"

        hls_list_sz = "6" if self.cfg.get("buffer_mode") == "normal" else "10"
        audio_sel = str(self.cfg.get("audio_track", "0")).strip().lower()
        map_args = ["-map", "0:v:0?"]
        if audio_sel in ("none", "off", "-1"):
            map_args += ["-an"]
        elif audio_sel == "all":
            map_args += ["-map", "0:a?"]
        else:
            try:
                a_idx = max(0, int(audio_sel))
            except ValueError:
                a_idx = 0
            map_args += ["-map", f"0:a:{a_idx}?"]

        cmd += [
            "-i", input_url,
            *map_args,
            "-sn", "-dn",
            "-map_metadata", "-1",
            "-map_chapters", "-1",
            "-c", "copy",
            "-mpegts_flags", "resend_headers+initial_discontinuity",
            "-max_muxing_queue_size", "4096",
            "-f", "hls",
            "-hls_time", str(HLS_SEG_TIME),
            "-hls_list_size", hls_list_sz,
            "-hls_delete_threshold", "4",
            "-hls_flags", "delete_segments+temp_file+independent_segments",
            "-hls_segment_filename", "seg_%06d.ts",
            "index.m3u8"
        ]
        return cmd

    async def _spawn_pushes(self):
        pushes_cfg = [p.strip() for p in self.cfg.get("pushes", []) if p and p.strip()]
        if not pushes_cfg:
            return
        is_astrag = (self.cfg.get("engine") == "astrag")
        if is_astrag:
            if self.status != "Online" or self.astrag_engine is None:
                return
            http_port = self.manager.config_data.get("http_port", 8080)
            tok = self.cfg.get("token", "").strip()
            tok_q = f"?token={tok}" if tok else ""
            input_arg = f"http://127.0.0.1:{http_port}/{self.name}/mpegts{tok_q}"
            cwd_arg = None
            pre_in_args = ["-threads", "1", "-probesize", "5000000", "-analyzeduration", "5000000"]
        else:
            m3u8_path = self.ram_dir / "index.m3u8"
            if not m3u8_path.exists() or len(list(self.ram_dir.glob("seg_*.ts"))) < 1:
                return
            input_arg = "index.m3u8"
            cwd_arg = str(self.ram_dir)
            pre_in_args = ["-threads", "1", "-probesize", "5000000", "-analyzeduration", "5000000", "-re", "-live_start_index", "-2"]
        for push_url in pushes_cfg:
            if push_url in self.push_procs:
                if self.push_procs[push_url].returncode is not None:
                    del self.push_procs[push_url]
                else:
                    continue

            target_url = push_url
            if target_url.startswith("srt://"):
                if "mode=caller" not in target_url:
                    port_m = re.search(r":(\d+)", target_url)
                    p_num = port_m.group(1) if port_m else "54333"
                    target_url = f"srt://0.0.0.0:{p_num}?mode=listener&pkt_size=1316&latency=200000"
                else:
                    if "pkt_size=" not in target_url:
                        target_url += ("&" if "?" in target_url else "?") + "pkt_size=1316"

            out_fmt = "mpegts" if target_url.startswith(("udp://", "srt://")) else "flv"
            cmd = [
                "ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                *pre_in_args,
                "-i", input_arg,
                "-map", "0:v:0?", "-map", "0:a?",
                "-c", "copy",
                "-f", out_fmt, target_url
            ]
            try:
                self.push_procs[push_url] = await asyncio.create_subprocess_exec(
                    *cmd, cwd=cwd_arg,
                    stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL
                )
            except Exception:
                pass

    async def _probe_codecs(self, seg_file: Path):
        try:
            async with self.manager.probe_sem:
                if not seg_file.exists():
                    return
                proc = await asyncio.create_subprocess_exec(
                    "ffprobe", "-v", "error", "-show_entries",
                    "stream=codec_name,width,height", "-of", "json", str(seg_file),
                    stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
                )
                out, _ = await asyncio.wait_for(proc.communicate(), timeout=4.0)
                info = json.loads(out.decode("utf-8", errors="ignore"))
                parts = []
                for st in info.get("streams", []):
                    cname = st.get("codec_name", "").upper()
                    if st.get("width"):
                        parts.append(f"{cname} {st['width']}x{st['height']}")
                    elif cname:
                        parts.append(cname)
                if parts:
                    self.codec_info = " / ".join(parts)
        except Exception:
            pass

    async def _sync_ram_to_dvr(self):
        if not self.ram_dir.exists():
            self.cached_buffer_sec = 0
            return
        try:
            entries = [e for e in os.scandir(self.ram_dir) if e.name.startswith("seg_") and e.name.endswith(".ts")]
        except OSError:
            return
        if not entries:
            self.cached_buffer_sec = 0
            return

        entries.sort(key=lambda e: e.name)
        self.cached_buffer_sec = min(self.target_buffer_seconds(), len(entries) * HLS_SEG_TIME)
        new_entries = [e for e in entries if e.name not in self.processed_segments]
        if not new_entries:
            return

        now = time.time()
        seg_dur = float(HLS_SEG_TIME)
        m3u8_p = self.ram_dir / "index.m3u8"
        if m3u8_p.exists():
            try:
                m_txt = m3u8_p.read_text(encoding="utf-8", errors="ignore")
                m_inf = re.findall(r"#EXTINF:([0-9.]+)", m_txt)
                if m_inf:
                    seg_dur = max(0.5, float(m_inf[-1]))
            except Exception:
                pass

        dvr_hours = int(self.cfg.get("dvr_hours", 0))
        for entry in new_entries:
            try:
                st_stat = entry.stat()
            except FileNotFoundError:
                continue
            if st_stat.st_size == 0:
                continue
            self.processed_segments.add(entry.name)
            if len(self.processed_segments) > 200:
                self.processed_segments = set(sorted(self.processed_segments)[-100:])

            self.last_segment_time = now
            self.status = "Online"

            seg_kbps = (st_stat.st_size * 8.0) / seg_dur / 1000.0
            self._kbps_samples.append(seg_kbps)
            if len(self._kbps_samples) > 6:
                self._kbps_samples.pop(0)
            self.bitrate_in_kbps = int(round(sum(self._kbps_samples) / len(self._kbps_samples)))

            seg_path = Path(entry.path)
            if not self.probed_once:
                self.probed_once = True
                asyncio.create_task(self._probe_codecs(seg_path))

            if dvr_hours > 0:
                ts_int = int(st_stat.st_mtime)
                day_str = time.strftime("%Y-%m-%d", time.gmtime(ts_int))
                target_dir = self.dvr_dir / day_str
                target_dir.mkdir(parents=True, exist_ok=True)
                target_file = target_dir / f"{ts_int}_{HLS_SEG_TIME}.ts"
                if not target_file.exists():
                    try:
                        await asyncio.to_thread(shutil.copy2, seg_path, target_file)
                    except Exception:
                        pass

    def _default_video_res(self) -> str:
        if self._probed_video_res:
            return self._probed_video_res
        hint = f"{self.name} {self.cfg.get('title', '')}".lower()
        if "4k" in hint or "uhd" in hint or "2160" in hint:
            return "3840x2160"
        if "720" in hint:
            return "1280x720"
        return "1920x1080"

    async def _probe_astrag_resolution(self):
        try:
            await asyncio.sleep(0.5)
            async with self.manager.probe_sem:
                if self.status != "Online" or self.astrag_engine is None:
                    return
                http_port = self.manager.config_data.get("http_port", 8080)
                tok = self.cfg.get("token", "").strip()
                tok_q = f"?token={tok}" if tok else ""
                probe_url = f"http://127.0.0.1:{http_port}/{self.name}/mpegts{tok_q}"
                proc = await asyncio.create_subprocess_exec(
                    "ffprobe", "-v", "error", "-probesize", "2000000", "-analyzeduration", "2000000",
                    "-select_streams", "v:0", "-show_entries", "stream=width,height", "-of", "json", probe_url,
                    stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
                )
                out, _ = await asyncio.wait_for(proc.communicate(), timeout=5.0)
                info = json.loads(out.decode("utf-8", errors="ignore"))
                for st_info in info.get("streams", []):
                    w_px = st_info.get("width")
                    h_px = st_info.get("height")
                    if w_px and h_px:
                        self._probed_video_res = f"{w_px}x{h_px}"
                        self._update_astrag_state()
                        break
        except Exception:
            pass

    def _update_astrag_state(self):
        eng = self.astrag_engine
        if eng is None:
            return
        if isinstance(eng, CoreEngine):
            st = CORE.stats.get(self.name, {}) if CORE is not None else {}
            a_tracks = st.get("audio_tracks", [])
            if a_tracks:
                self.detected_audio_tracks = list(a_tracks)
            pids = st.get("pids", [])
            if pids or a_tracks:
                v_map = {0x1B: "H264", 0x24: "HEVC", 0x02: "MPEG2", 0x01: "MPEG1"}
                a_map = {0x0F: "AAC", 0x11: "AAC-LATM", 0x81: "AC3", 0x06: "AC3", 0x87: "EAC3", 0x03: "MP2", 0x04: "MP2"}
                v_res = self._default_video_res()
                tracks = []
                for _pid, kind, stype in pids:
                    if kind == 1:
                        tracks.append(f"{v_map.get(stype, 'H264')} {v_res}")
                if not tracks and pids:
                    tracks.append(f"H264 {v_res}")
                audio_sel = str(self.cfg.get("audio_track", "0")).strip().lower()
                if audio_sel in ("none", "off", "-1"):
                    pass
                elif a_tracks:
                    for tr in a_tracks:
                        idx = int(tr.get("index", 0))
                        is_sel = (
                            audio_sel == "all"
                            or str(idx) == audio_sel
                            or (audio_sel.isdigit() and int(audio_sel) >= len(a_tracks) and idx == 0)
                        )
                        if is_sel:
                            ac = tr.get("codec", "AAC")
                            if tr.get("lang"):
                                ac = f"{ac} ({tr['lang']})"
                            tracks.append(ac)
                else:
                    for _pid, kind, stype in pids:
                        if kind == 2:
                            tracks.append(a_map.get(stype, "AAC"))
                if tracks:
                    self.codec_info = " / ".join(tracks)
            if st.get("onair"):
                self.cached_buffer_sec = min(self.target_buffer_seconds(), max(1, int(round(eng.seg_dur * eng.max_segs))))
                if not self.probed_once:
                    self.probed_once = True
                    asyncio.create_task(self._probe_astrag_resolution())
            else:
                self.cached_buffer_sec = 0
            return

        hls_act_fn = getattr(eng, "is_hls_active", None) or getattr(eng, "_is_hls_active", None)
        if (callable(hls_act_fn) and hls_act_fn() and
                not getattr(eng, "_segments", None) and
                not getattr(eng, "_seen_video_keyframes", False) and
                len(getattr(eng, "_current", b"")) >= 188 * 128):
            if (time.monotonic() - getattr(eng, "_created", time.monotonic())) >= 2.0:
                try:
                    eng._finish_segment()
                except Exception:
                    pass

        a_tracks = getattr(eng, "_audio_tracks_info", None)
        if a_tracks:
            self.detected_audio_tracks = list(a_tracks)

        elem_pids = getattr(eng, "_elementary_pids", {})
        if elem_pids:
            v_codec = getattr(eng, "_video_codec_name", "H264")
            v_res = getattr(eng, "_video_resolution", "") or self._default_video_res()
            tracks = []
            for pid_k, tname in elem_pids.items():
                if tname == "VIDEO":
                    tracks.append(f"{v_codec} {v_res}")
                elif tname == "AUDIO":
                    acodec = "AAC"
                    for tr in (a_tracks or []):
                        if tr.get("pid") == pid_k:
                            acodec = tr.get("codec", "AAC")
                            if tr.get("lang"):
                                acodec = f"{acodec} ({tr['lang']})"
                            break
                    tracks.append(acodec)
            if tracks:
                self.codec_info = " / ".join(tracks)

        segs_dict = getattr(eng, "_segments", {})
        cur_el = float(eng._elapsed_segment()) if hasattr(eng, "_elapsed_segment") else 0.0
        if segs_dict or cur_el > 0.2:
            total_dur = sum(max(0.2, float(getattr(s, "duration", 2.0))) for s in segs_dict.values()) + cur_el
            if getattr(eng, "_is_hls_input", False):
                total_dur = max(total_dur, 6.0)
            self.cached_buffer_sec = min(self.target_buffer_seconds(), max(1, int(round(total_dur))))
            dvr_hours = int(self.cfg.get("dvr_hours", 0))
            if dvr_hours > 0:
                cur_seq = int(getattr(eng, "_sequence", 0))
                if cur_seq != self._last_synced_seq:
                    self._last_synced_seq = cur_seq
                    latest_seg = next(reversed(segs_dict.values()), None)
                    if latest_seg is not None:
                        seg_bytes = latest_seg.data if isinstance(latest_seg.data, bytes) else bytes(latest_seg.data)
                        if seg_bytes:
                            ts_int = int(time.time())
                            day_str = time.strftime("%Y-%m-%d", time.gmtime(ts_int))
                            target_dir = self.dvr_dir / day_str
                            target_dir.mkdir(parents=True, exist_ok=True)
                            target_file = target_dir / f"{ts_int}_{max(1, int(round(latest_seg.duration)))}.ts"
                            if not target_file.exists():
                                try:
                                    target_file.write_bytes(seg_bytes)
                                except Exception:
                                    pass
        else:
            self.cached_buffer_sec = 0

    async def _probe_upper_inputs(self, upper_urls: List[str]):
        if self._probing_upper or not upper_urls or not self.manager.http_client:
            return
        self._probing_upper = True
        try:
            for idx_u, raw_u in enumerate(upper_urls):
                base_u = normalize_input_url(raw_u).split("#", 1)[0].strip()
                if not base_u.startswith(("http://", "https://")):
                    continue
                try:
                    req_hdrs = {"User-Agent": (self.cfg.get("user_agent") or "Lavf/60.16.100")}
                    async with self.manager.http_client.get(
                        base_u,
                        headers=req_hdrs,
                        timeout=ClientTimeout(total=4, connect=2, sock_read=2)
                    ) as resp:
                        if resp.status == 200:
                            chunk = await resp.content.read(564)
                            if chunk and (len(chunk) >= 188 or b"#EXTM3U" in chunk or b"#EXT-X-" in chunk):
                                if self.active_input_idx > idx_u:
                                    self.active_input_idx = idx_u
                                    self.engine_error = False
                                    await self._kill_ffmpeg()
                                return
                except Exception:
                    pass
        finally:
            self._probing_upper = False

    async def _lifecycle_loop(self):
        while not self.stop_event.is_set():
            if not self.cfg.get("enabled", True) or not self.cfg.get("inputs"):
                self.status = "Disabled"
                self.engine_error = False
                self.started_at = None
                await self._kill_ffmpeg()
                shutil.rmtree(self.ram_dir, ignore_errors=True)
                await asyncio.sleep(0.6)
                continue

            is_astrag = (self.cfg.get("engine") == "astrag")

            if is_astrag:
                if self.proc is not None:
                    await self._kill_ffmpeg()

                raw_inputs = [i.strip() for i in self.cfg.get("inputs", []) if i.strip()]
                if not raw_inputs:
                    self.status = "Error"
                    self.engine_error = True
                    self.bitrate_in_kbps = 0.0
                    await asyncio.sleep(1.5)
                    continue

                if self.astrag_engine is None:
                    norm_inputs = [normalize_input_url(u) for u in raw_inputs]
                    self.active_input_idx = self.active_input_idx % len(norm_inputs)
                    self._base_astrag_idx = self.active_input_idx
                    ordered_urls = norm_inputs[self.active_input_idx:] + norm_inputs[:self.active_input_idx]

                    shutil.rmtree(self.ram_dir, ignore_errors=True)
                    self.processed_segments.clear()
                    self.probed_once = False

                    audio_sel = str(self.cfg.get("audio_track", "0")).strip().lower() or "0"
                    ua_cfg = (self.cfg.get("user_agent") or "").strip()
                    default_ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
                    is_ondemand_relay = (self.cfg.get("mode") == "ondemand" or bool(self.cfg.get("_cluster_host")))
                    idle_sec_opt = max(15, int(self.cfg.get("clients_timeout", 25)))
                    core_urls = []
                    for u in ordered_urls:
                        base_u, *frag_parts = u.split("#", 1)
                        opts = [
                            p for p in (frag_parts[0].split("&") if frag_parts else [])
                            if p and not p.startswith("audio_track=") and p != "keep_active" and not p.startswith("idle_delay=")
                        ]
                        opts.append(f"audio_track={audio_sel}")
                        if not is_ondemand_relay:
                            opts.append("keep_active")
                        else:
                            opts.append(f"idle_delay={idle_sec_opt}")
                        if ua_cfg and ua_cfg != default_ua and not any(p.startswith("ua=") for p in opts):
                            opts.append(f"ua={ua_cfg}")
                        core_urls.append(f"{base_u}#{'&'.join(opts)}")

                    astrag_cfg = {
                        "id": self.name,
                        "name": self.cfg.get("title") or self.name,
                        "input": core_urls,
                        "output": [],
                        "audio_track": audio_sel,
                    }
                    if self.cfg.get("_cluster_host"):
                        astrag_cfg["_cluster_host"] = self.cfg.get("_cluster_host")
                    if ua_cfg and ua_cfg != default_ua:
                        astrag_cfg["user_agent"] = ua_cfg

                    seg_dur = 3.0
                    max_segs = 5
                    try:
                        if _core_eligible(astrag_cfg):
                            self.astrag_engine = CoreEngine(astrag_cfg, seg_dur, max_segs).start()
                        else:
                            self.astrag_engine = AstraGEngine(
                                ordered_urls,
                                outputs=[],
                                segment_duration=seg_dur,
                                max_segments=max_segs,
                                max_segment_bytes=4 * 1024 * 1024,
                                max_hls_bytes=10 * 1024 * 1024,
                                stream_options=astrag_cfg,
                            )
                            await self.astrag_engine.start()
                        self.started_at = time.time()
                        self.last_segment_time = time.time()
                        self._last_astrag_pkts = 0
                        self._last_astrag_pkt_ts = time.time()
                        if not self.engine_error and self.status != "Online":
                            self.status = "Waiting"
                    except Exception as e:
                        self.codec_info = f"ERR: {str(e)[:55]}"
                        self.status = "Error"
                        self.engine_error = True
                        self.bitrate_in_kbps = 0.0
                        await self._kill_ffmpeg()
                        self.active_input_idx = (self.active_input_idx + 1) % len(norm_inputs)
                        await asyncio.sleep(2.5)
                        continue

                self._update_astrag_state()
                await self._spawn_pushes()

                eng = self.astrag_engine
                if isinstance(eng, CoreEngine):
                    st = CORE.stats.get(self.name, {}) if CORE is not None else {}
                    onair = bool(st.get("onair", False))
                    raw_bps = float(st.get("bitrate", 0.0) or 0.0)
                    pkts = int(st.get("packets", 0) or 0)
                    last_err = st.get("last_error")
                    if raw_inputs:
                        eng_idx = max(1, int(st.get("input_id", 1) or 1)) - 1
                        self.active_input_idx = (self._base_astrag_idx + eng_idx) % len(raw_inputs)
                    if last_err == "idle":
                        self.status = "Waiting"
                        self.engine_error = False
                        self.bitrate_in_kbps = 0.0
                        if self.codec_info.startswith("ERR:"):
                            self.codec_info = "On-Demand (Idle Sleep)"
                    elif onair or (pkts > 0 and raw_bps > 0):
                        self.status = "Online"
                        self.engine_error = False
                        self.bitrate_in_kbps = max(1, int(round(raw_bps / 1000.0)))
                        self.last_segment_time = time.time()
                        if self.codec_info.startswith("ERR:") or self.codec_info == "On-Demand (Idle Sleep)":
                            self.codec_info = "Pass-through (-c copy)"
                        if self.active_input_idx > 0 and (time.time() - self._last_upper_probe_ts) > 20.0:
                            self._last_upper_probe_ts = time.time()
                            asyncio.create_task(self._probe_upper_inputs(raw_inputs[:self.active_input_idx]))
                    elif last_err and (time.monotonic() - eng._started) > 8.0:
                        self.codec_info = f"ERR: {str(last_err)[:55]}"
                        self.status = "Error"
                        self.engine_error = True
                        self.bitrate_in_kbps = 0.0
                    else:
                        if self.status != "Online":
                            self.status = "Waiting"
                        self.bitrate_in_kbps = 0.0
                    await asyncio.sleep(1.0)
                    continue

                counts = getattr(eng, "_counts", {}) if eng else {}
                pkts = int(counts.get("packets", 0) or 0)
                st = eng.stats(include_pids=False) if eng else {}
                raw_bps = float(st.get("effective_bitrate") or st.get("pcr_bitrate") or st.get("bitrate") or 0.0)
                now_ts = time.time()

                if pkts > self._last_astrag_pkts:
                    self._last_astrag_pkts = pkts
                    self._last_astrag_pkt_ts = now_ts
                    self.last_segment_time = now_ts
                    if pkts >= 16 or len(getattr(eng, "_segments", {})) > 0:
                        self.status = "Online"
                        self.engine_error = False
                        self.bitrate_in_kbps = max(1, int(round(raw_bps / 1000.0)))
                        if self.codec_info.startswith("ERR:"):
                            self.codec_info = "Pass-through (-c copy)"

                if eng is not None and raw_inputs:
                    eng_idx = max(1, int(getattr(eng, "_active_input_id", 1))) - 1
                    self.active_input_idx = (self._base_astrag_idx + eng_idx) % len(raw_inputs)
                if self.status == "Online" and self.active_input_idx > 0 and (now_ts - self._last_upper_probe_ts) > 20.0:
                    self._last_upper_probe_ts = now_ts
                    asyncio.create_task(self._probe_upper_inputs(raw_inputs[:self.active_input_idx]))
                last_err = getattr(eng, "_last_error", None)
                idle_pkt_sec = now_ts - (self._last_astrag_pkt_ts or now_ts)
                if last_err and idle_pkt_sec > 15.0:
                    self.codec_info = f"ERR: {str(last_err)[:55]}"
                    self.status = "Error"
                    self.engine_error = True
                    self.bitrate_in_kbps = 0.0

                await asyncio.sleep(0.4 if self.status != "Online" else 1.0)
                continue

            if self.astrag_engine is not None:
                await self._kill_ffmpeg()

            if self.cfg.get("mode") == "ondemand":
                idle_sec = time.time() - self.last_client_time
                timeout_sec = max(30, int(self.cfg.get("clients_timeout", 45)))
                if self.active_clients_count() == 0 and idle_sec > timeout_sec:
                    if self.proc is not None:
                        await self._kill_ffmpeg()
                        shutil.rmtree(self.ram_dir, ignore_errors=True)
                    self.status = "Waiting"
                    self.engine_error = False
                    self.started_at = None
                    await asyncio.sleep(1.0)
                    continue

            if self.proc is not None and self.proc.returncode is not None:
                try:
                    err_bytes = await self.proc.stderr.read()
                    lines = [l.strip() for l in err_bytes.decode("utf-8", errors="ignore").splitlines() if l.strip()]
                    if lines:
                        self.codec_info = f"ERR: {lines[-1][:65]}"
                except Exception:
                    pass
                self.status = "Error"
                self.engine_error = True
                await self._kill_ffmpeg()
                inputs = [i for i in self.cfg.get("inputs", []) if i.strip()]
                if inputs:
                    self.active_input_idx = (self.active_input_idx + 1) % len(inputs)
                await asyncio.sleep(3.0)

            if self.proc is None:
                inputs = [i for i in self.cfg.get("inputs", []) if i.strip()]
                if not inputs:
                    self.status = "Error"
                    self.engine_error = True
                    await asyncio.sleep(3.0)
                    continue
                self.active_input_idx = self.active_input_idx % len(inputs)
                current_url = inputs[self.active_input_idx]

                shutil.rmtree(self.ram_dir, ignore_errors=True)
                self.ram_dir.mkdir(parents=True, exist_ok=True)
                self.processed_segments.clear()
                self.probed_once = False

                resolved_url = await self._resolve_best_variant_url(current_url)
                cmd = self._build_primary_hls_cmd(resolved_url)
                try:
                    self.proc = await asyncio.create_subprocess_exec(
                        *cmd,
                        cwd=str(self.ram_dir),
                        stdout=asyncio.subprocess.DEVNULL,
                        stderr=asyncio.subprocess.DEVNULL
                    )
                    self.started_at = time.time()
                    self.last_segment_time = time.time()
                    if self.status != "Online" and not self.engine_error:
                        self.status = "Waiting"
                except Exception as e:
                    self.codec_info = f"ERR: {str(e)[:50]}"
                    self.status = "Error"
                    self.engine_error = True
                    self.active_input_idx = (self.active_input_idx + 1) % len(inputs)
                    await asyncio.sleep(3.0)
                    continue

            await self._sync_ram_to_dvr()
            if self.status == "Online":
                self.engine_error = False
                inputs = [i.strip() for i in self.cfg.get("inputs", []) if i.strip()]
                if self.active_input_idx > 0 and inputs and (time.time() - self._last_upper_probe_ts) > 20.0:
                    self._last_upper_probe_ts = time.time()
                    asyncio.create_task(self._probe_upper_inputs(inputs[:self.active_input_idx]))
            await self._spawn_pushes()

            cfg_to = max(8, int(self.cfg.get("source_timeout", 15)))
            src_timeout = max(25, cfg_to) if self.status == "Online" else cfg_to
            if time.time() - self.last_segment_time > src_timeout:
                self.status = "Error"
                self.engine_error = True
                await self._kill_ffmpeg()
                inputs = [i for i in self.cfg.get("inputs", []) if i.strip()]
                if inputs:
                    self.active_input_idx = (self.active_input_idx + 1) % len(inputs)
                await asyncio.sleep(2.0)
                continue

            await asyncio.sleep(1.0)


class StreamManager:
    def __init__(self):
        self.config_data = {
            "http_port": 8080,
            "admin_user": "admin",
            "admin_pass": "admin",
            "ui_theme": "2",
            "ui_lang": "ru",
            "dvr_root": "/var/lib/flustream/dvr",
            "dvr_disk_limit": 85,
            "global_auth_url": "",
            "cluster_key": "flustream_secret",
            "peers": [],
            "cluster_sources": [],
            "servers": [],
            "streams": []
        }
        self.workers: Dict[str, StreamWorker] = {}
        self.sessions: Dict[str, PlaySession] = {}
        self.http_client: Optional[ClientSession] = None
        self.pulse_history: List[dict] = []
        self._last_net_io = psutil.net_io_counters()
        self._last_net_ts = time.time()
        self.nic_in_mbps: float = 0.0
        self.nic_out_mbps: float = 0.0
        self.cached_cpu: float = 0.0
        self.cached_ram: float = 0.0
        self.cached_shm_mb: float = 0.0
        self.cached_dvr_percent: float = 0.0
        self.cached_dvr_free_gb: float = 0.0
        self.cached_raw_conf: str = ""
        self.active_clients_map: Dict[str, int] = {}
        self.non_hls_urls: set = set()
        self.hls_urls: set = set()
        self.probe_sem = asyncio.Semaphore(1)
        self.cluster_cache: Dict[str, dict] = {}
        self.cluster_aliases: Dict[str, str] = {}
        self.cluster_node_status: Dict[str, dict] = {}

    def resolve_stream_name(self, name: str) -> str:
        if name in self.workers:
            return name
        alias = self.cluster_aliases.get(name)
        if alias and alias in self.workers:
            return alias
        return name

    def make_admin_token(self) -> str:
        u = self.config_data.get("admin_user", "admin")
        p = self.config_data.get("admin_pass", "admin")
        return hmac.new(f"streamflow_aria:{p}".encode(), u.encode(), hashlib.sha256).hexdigest()

    def is_admin_authenticated(self, req: web.Request) -> bool:
        expected = self.make_admin_token()
        cookie_val = req.cookies.get(COOKIE_NAME, "")
        if cookie_val and hmac.compare_digest(cookie_val, expected):
            return True
        auth_hdr = req.headers.get("Authorization", "")
        if auth_hdr.startswith("Basic "):
            try:
                decoded = base64.b64decode(auth_hdr[6:]).decode("utf-8")
                user, pw = decoded.split(":", 1)
                if user == self.config_data.get("admin_user") and pw == self.config_data.get("admin_pass"):
                    return True
            except Exception:
                pass
        return False

    async def init(self):
        self.http_client = ClientSession(
            timeout=ClientTimeout(total=25),
            connector=TCPConnector(ssl=False, limit=64)
        )
        RAM_ROOT.mkdir(parents=True, exist_ok=True)
        DVR_ROOT.mkdir(parents=True, exist_ok=True)
        if STATE_JSON.exists():
            try:
                loaded = json.loads(STATE_JSON.read_text(encoding="utf-8"))
                if isinstance(loaded.get("admin_user"), list):
                    loaded["admin_user"] = loaded["admin_user"][0]
                self.config_data.update(loaded)
            except Exception:
                pass
        if CONFIG_FILE.exists() and (not STATE_JSON.exists() or CONFIG_FILE.stat().st_mtime >= STATE_JSON.stat().st_mtime):
            self.config_data = parse_flustream_conf(CONFIG_FILE.read_text(encoding="utf-8"), self.config_data)

        if str(self.config_data.get("ui_theme")) not in ("2", "4"):
            self.config_data["ui_theme"] = "2"
        if str(self.config_data.get("ui_lang")) not in ("ru", "en"):
            self.config_data["ui_lang"] = "ru"

        self.config_data.setdefault("streams", [])
        self.config_data.setdefault("servers", [])
        # Strip any runtime _cluster_host streams or _cluster_auto_inputs saved previously
        clean_local = []
        for s in self.config_data.get("streams", []):
            if s.get("_cluster_host"):
                continue
            auto_in = set(s.get("_cluster_auto_inputs") or [])
            if auto_in:
                s["inputs"] = [u for u in s.get("inputs", []) if u not in auto_in]
                s.pop("_cluster_auto_inputs", None)
                s.pop("_cluster_backups", None)
            clean_local.append(s)
        self.config_data["streams"] = clean_local

        self.save_configs()
        await self.apply_streams()
        asyncio.create_task(self._dvr_cleaner_loop())
        asyncio.create_task(self._cluster_sync_loop())
        asyncio.create_task(self._pulse_sampler_loop())

    def save_configs(self):
        CONFIG_FILE.parent.mkdir(parents=True, exist_ok=True)
        # Do not persist dynamic cluster streams or auto-injected backup inputs into STATE_JSON
        save_copy = dict(self.config_data)
        clean_streams = []
        for s in self.config_data.get("streams", []):
            if s.get("_cluster_host"):
                continue
            s_copy = dict(s)
            auto_in = set(s_copy.pop("_cluster_auto_inputs", None) or [])
            s_copy.pop("_cluster_backups", None)
            if auto_in:
                s_copy["inputs"] = [u for u in s_copy.get("inputs", []) if u not in auto_in]
            clean_streams.append(s_copy)
        save_copy["streams"] = clean_streams
        STATE_JSON.write_text(json.dumps(save_copy, indent=2, ensure_ascii=False), encoding="utf-8")
        self.cached_raw_conf = generate_flustream_conf(save_copy)
        CONFIG_FILE.write_text(self.cached_raw_conf, encoding="utf-8")

    async def apply_streams(self):
        new_map = {s["name"]: s for s in self.config_data.get("streams", [])}
        for name in list(self.workers.keys()):
            if name not in new_map:
                await self.workers[name].stop()
                del self.workers[name]
        for name, scfg in new_map.items():
            if name in self.workers:
                w = self.workers[name]
                old_cfg = w.cfg
                w.cfg = scfg
                w.touch_client()
                if (
                    old_cfg.get("inputs") != scfg.get("inputs")
                    or old_cfg.get("enabled") != scfg.get("enabled")
                    or old_cfg.get("mode") != scfg.get("mode")
                    or old_cfg.get("quality", "best") != scfg.get("quality", "best")
                    or old_cfg.get("buffer_mode", "30s") != scfg.get("buffer_mode", "30s")
                    or old_cfg.get("user_agent", "") != scfg.get("user_agent", "")
                    or old_cfg.get("engine", "ffmpeg") != scfg.get("engine", "ffmpeg")
                    or str(old_cfg.get("audio_track", "0")) != str(scfg.get("audio_track", "0"))
                ):
                    w.engine_error = False
                    w.status = "Waiting" if scfg.get("enabled", True) else "Disabled"
                    await w._kill_ffmpeg()
            else:
                w = StreamWorker(scfg, self)
                self.workers[name] = w
                w.start()

    async def check_auth(self, stream_name: str, req: web.Request) -> bool:
        w = self.workers.get(stream_name)
        if not w:
            return False
        token_req = w.cfg.get("token", "").strip()
        client_token = req.query.get("token", "")
        if token_req and client_token != token_req:
            return False
        auth_url = w.cfg.get("on_play", "").strip() or self.config_data.get("global_auth_url", "").strip()
        if auth_url and self.http_client:
            try:
                params = {"name": stream_name, "ip": _client_ip(req), "token": client_token, "proto": req.path}
                async with self.http_client.get(auth_url, params=params) as resp:
                    if resp.status != 200:
                        return False
            except Exception:
                return False
        return True

    def register_session(self, stream_name: str, req: web.Request, proto: str, bytes_delta: int = 0) -> PlaySession:
        ip = _client_ip(req)
        key = f"{stream_name}:{ip}:{proto}"
        sess = self.sessions.get(key)
        if sess is None:
            ua = req.headers.get("User-Agent", "Player")
            sess = PlaySession(key, stream_name, ip, proto, ua)
            self.sessions[key] = sess
        sess.last_seen = time.time()
        sess.bytes_sent += bytes_delta
        return sess

    def _apply_cluster_cache_to_streams(self):
        servers = self.config_data.get("servers", [])
        cluster_hosts = set()
        remote_ids_all = set()
        for srv in servers:
            if isinstance(srv, dict) and srv.get("host"):
                rh = str(srv.get("host") or "").strip().lower()
                rp = int(srv.get("port") or 8000)
                cluster_hosts.add(rh)
                rcfg = self.cluster_cache.get(f"{rh}:{rp}") or self.cluster_cache.get(f"{srv.get('host')}:{rp}")
                if isinstance(rcfg, dict):
                    for rs in rcfg.get("make_stream", []) or []:
                        if isinstance(rs, dict):
                            rid = str(rs.get("id") or rs.get("name") or "").strip()
                            if rid:
                                remote_ids_all.add(rid)
                                remote_ids_all.add(re.sub(r"[^a-zA-Z0-9_\-]", "_", rid))

        def _is_stale_cluster_or_dvb_input(u: str) -> bool:
            u_str = str(u or "").strip()
            if not u_str:
                return True
            if u_str.lower().startswith("dvb://"):
                return True
            try:
                sp = urlsplit(u_str.split("#", 1)[0])
                h = (sp.hostname or "").strip().lower()
                if h and h in cluster_hosts:
                    return True
            except Exception:
                pass
            return False

        local_streams = []
        for s in self.config_data.get("streams", []):
            if s.get("_cluster_host"):
                continue
            auto_in = set(s.get("_cluster_auto_inputs") or [])
            orig_inputs = [u for u in s.get("inputs", []) if u not in auto_in and not str(u).strip().lower().startswith("dvb://")]
            if orig_inputs and all(_is_stale_cluster_or_dvb_input(u) for u in orig_inputs) and str(s.get("name", "")) in remote_ids_all:
                # Stream was previously a cluster stream saved with stale cluster/dvb inputs; let cluster sync recreate it cleanly
                continue
            cleaned_inputs = []
            for u in orig_inputs:
                try:
                    sp = urlsplit(str(u).split("#", 1)[0])
                    h = (sp.hostname or "").strip().lower()
                    if h and h in cluster_hosts:
                        # Remove old auto-injected cluster URLs (with user:pass@, /mpegts, /index.m3u8, or missing token) so fresh one is attached below
                        continue
                except Exception:
                    pass
                cleaned_inputs.append(u)
            s["inputs"] = cleaned_inputs
            s["_cluster_auto_inputs"] = []
            s["_cluster_backups"] = []
            local_streams.append(s)

        local_ids = {str(s.get("name", "")) for s in local_streams if isinstance(s, dict)}
        local_by_norm_key: Dict[str, List[dict]] = {}
        for s in local_streams:
            for cand in (s.get("name", ""), s.get("title", "")):
                nk = _normalize_channel_match_key(str(cand or ""))
                if nk:
                    local_by_norm_key.setdefault(nk, [])
                    if s not in local_by_norm_key[nk]:
                        local_by_norm_key[nk].append(s)

        cluster_streams = []
        cluster_aliases: Dict[str, str] = {}
        used_ids = set(local_ids)

        for idx, srv in enumerate(servers):
            if not isinstance(srv, dict) or not srv.get("enabled", True):
                continue
            rhost = str(srv.get("host") or "").strip()
            rport = int(srv.get("port") or 8000)
            if not rhost:
                continue
            rlogin = str(srv.get("login") or "").strip()
            rpass = str(srv.get("password") or "")
            srv_name = str(srv.get("name") or rhost).strip()
            srv_mode = str(srv.get("import_mode") or "ondemand").strip()
            srv_type = str(srv.get("type") or "auto").strip().lower()
            host_port = f"{rhost}:{rport}"
            rcfg = self.cluster_cache.get(host_port)
            if not isinstance(rcfg, dict):
                continue
            rsettings = rcfg.get("settings") if isinstance(rcfg.get("settings"), dict) else {}
            r_http_port = int(rsettings.get("http_play_port") or rcfg.get("http_port") or srv.get("play_port") or rport)
            for raw_s in rcfg.get("make_stream", []) or []:
                if not isinstance(raw_s, dict) or not raw_s.get("enable", True):
                    continue
                orig_id = str(raw_s.get("id") or raw_s.get("name") or "").strip()
                orig_id_clean = re.sub(r"[^a-zA-Z0-9_\-]", "_", orig_id)
                if not orig_id_clean:
                    continue
                rtitle = str(raw_s.get("name") or raw_s.get("title") or orig_id).strip()
                c_inputs = _build_cluster_stream_inputs(
                    raw_s,
                    rhost,
                    rport,
                    play_port=r_http_port,
                    rlogin=rlogin,
                    rpass=rpass,
                    srv_type=srv_type,
                    remote_cfg=rcfg,
                )
                if not c_inputs:
                    continue

                # Check if any local channel matches by ID or case/font-insensitive name/title (e.g. Боец / боец / БОЕЦ)
                matched_locals: List[dict] = []
                for cand in (orig_id, orig_id_clean, rtitle):
                    nk = _normalize_channel_match_key(cand)
                    if nk and nk in local_by_norm_key:
                        for ls in local_by_norm_key[nk]:
                            if ls not in matched_locals:
                                matched_locals.append(ls)

                primary_cluster_url = c_inputs[0]
                for ls in matched_locals:
                    cur_in = ls.setdefault("inputs", [])
                    if primary_cluster_url not in cur_in:
                        cur_in.append(primary_cluster_url)
                        ls.setdefault("_cluster_auto_inputs", []).append(primary_cluster_url)
                    ls.setdefault("_cluster_backups", []).append({
                        "server": srv_name,
                        "host_port": host_port,
                        "remote_id": orig_id,
                        "url": primary_cluster_url
                    })

                if orig_id_clean not in used_ids:
                    cid = orig_id_clean
                else:
                    cid = f"c{idx + 1}_{orig_id_clean}"
                    suffix = 2
                    while cid in used_ids:
                        cid = f"c{idx + 1}_{orig_id_clean}_{suffix}"
                        suffix += 1
                used_ids.add(cid)

                cluster_aliases.setdefault(orig_id_clean, cid)
                cluster_aliases.setdefault(orig_id, cid)
                cluster_aliases[f"c{idx + 1}_{orig_id_clean}"] = cid
                cluster_aliases[f"cluster/{host_port}/{orig_id}"] = cid
                cluster_aliases[f"cluster/{rhost}/{orig_id}"] = cid
                cluster_aliases[f"cluster/c{idx + 1}/{orig_id}"] = cid

                # Standalone cluster relay channel (On-Demand Relay by default: 0% CPU and 0 Mbps when idle)
                display_title = f"[{srv_name}] {rtitle}" if rtitle and not rtitle.startswith("[") else (rtitle or cid)
                cs_obj = {
                    "name": cid,
                    "title": display_title,
                    "mode": "stream" if srv_mode == "stream" else "ondemand",
                    "engine": "astrag",
                    "audio_track": str(raw_s.get("audio_track", "0")),
                    "quality": "best",
                    "buffer_mode": "30s",
                    "user_agent": str(raw_s.get("user_agent") or ""),
                    "enabled": True,
                    "inputs": c_inputs,
                    "source_timeout": 20,
                    "clients_timeout": 25,
                    "dvr_hours": 0,
                    "pushes": [],
                    "token": "",
                    "on_play": "",
                    "_cluster_host": host_port,
                    "_cluster_srv_name": srv_name,
                    "_cluster_orig_id": orig_id,
                    "_cluster_type": str(srv.get("type") or "astrag")
                }
                cluster_streams.append(cs_obj)

        self.cluster_aliases = cluster_aliases
        self.config_data["streams"] = local_streams + cluster_streams

    async def _sync_cluster_servers(self) -> dict:
        servers = self.config_data.get("servers", [])
        if not servers or not self.http_client:
            self._apply_cluster_cache_to_streams()
            await self.apply_streams()
            return {"synced_nodes": 0, "total_streams": 0, "errors": []}

        synced_nodes = 0
        total_remote_streams = 0
        errors = []
        ckey = self.config_data.get("cluster_key", "")

        for idx, srv in enumerate(servers):
            if not isinstance(srv, dict) or not srv.get("enabled", True):
                continue
            rhost = str(srv.get("host") or "").strip()
            rport = int(srv.get("port") or 8000)
            if not rhost:
                continue
            rlogin = str(srv.get("login") or "").strip()
            rpass = str(srv.get("password") or "")
            srv_type = str(srv.get("type") or "auto").strip().lower()
            host_port = f"{rhost}:{rport}"

            headers = {"Content-Type": "application/json", "User-Agent": "StreamFlow-Aria-Cluster/4.2"}
            if rlogin:
                b64 = base64.b64encode(f"{rlogin}:{rpass}".encode("utf-8")).decode("ascii")
                headers["Authorization"] = f"Basic {b64}"
            if ckey:
                headers["X-Cluster-Key"] = ckey

            fetched_cfg = None
            last_err = "недоступен"

            # 1. Try AstraG / Astra Cesbo / StreamFlow Aria POST /control/ {"cmd": "load"}
            if srv_type in ("auto", "astrag", "astra", "cesbo", "streamflow"):
                for ctrl_path in ("/control/", "/control"):
                    try:
                        url = f"http://{rhost}:{rport}{ctrl_path}"
                        async with self.http_client.post(
                            url,
                            json={"cmd": "load"},
                            headers=headers,
                            timeout=ClientTimeout(total=6, connect=3)
                        ) as resp:
                            last_err = f"HTTP {resp.status}"
                            if resp.status == 200:
                                data = await resp.json(content_type=None)
                                if isinstance(data, dict) and isinstance(data.get("make_stream"), list):
                                    fetched_cfg = data
                                    break
                    except Exception as e:
                        last_err = str(e)[:60]

            # 2. Fallback: StreamFlow Aria / Flussonic v3 REST API
            if fetched_cfg is None and srv_type in ("auto", "streamflow", "flussonic", "astrag"):
                for ep in (
                    f"http://{rhost}:{rport}/api/v3/cluster/streams",
                    f"http://{rhost}:{rport}/streamer/api/v3/streams?limit=2000&select=name,title",
                    f"http://{rhost}:{rport}/flussonic/api/media",
                ):
                    try:
                        async with self.http_client.get(
                            ep,
                            headers=headers,
                            timeout=ClientTimeout(total=6, connect=3)
                        ) as resp:
                            last_err = f"HTTP {resp.status}"
                            if resp.status != 200:
                                continue
                            j = await resp.json(content_type=None)
                            if isinstance(j, dict) and isinstance(j.get("streams"), list):
                                ms_list = []
                                for rs in j["streams"]:
                                    if not isinstance(rs, dict):
                                        continue
                                    sid = str(rs.get("name") or rs.get("id") or "").strip()
                                    if not sid:
                                        continue
                                    ms_list.append({
                                        "id": sid,
                                        "name": str(rs.get("title") or sid),
                                        "enable": not bool(rs.get("disabled", False)),
                                        "input": rs.get("inputs") or rs.get("input") or [f"http://{rhost}:{rport}/{sid}/mpegts", f"http://{rhost}:{rport}/{sid}/index.m3u8"],
                                        "output": rs.get("output") or [],
                                    })
                                fetched_cfg = {"http_port": rport, "make_stream": ms_list}
                                break
                    except Exception as e:
                        last_err = str(e)[:60]

            # 3. Fallback: M3U playlist (/playlist.m3u8 or /playlist.m3u)
            if fetched_cfg is None:
                for ep in (f"http://{rhost}:{rport}/playlist.m3u8", f"http://{rhost}:{rport}/playlist.m3u"):
                    try:
                        async with self.http_client.get(
                            ep,
                            headers=headers,
                            timeout=ClientTimeout(total=6, connect=3)
                        ) as resp:
                            if resp.status == 200:
                                text_body = await resp.text()
                                if text_body.lstrip().startswith("#EXTM3U"):
                                    ms_list = []
                                    cur_title = ""
                                    for line in text_body.splitlines():
                                        line = line.strip()
                                        if line.startswith("#EXTINF:"):
                                            cur_title = line.split(",", 1)[-1].strip()
                                        elif line.startswith(("http://", "https://")):
                                            parts = line.split("?")[0].rstrip("/").split("/")
                                            sname = parts[-2] if parts[-1] in ("index.m3u8", "video.m3u8", "mpegts") and len(parts) >= 2 else parts[-1].replace(".m3u8", "").replace(".ts", "")
                                            sname = re.sub(r"[^a-zA-Z0-9_\-]", "", sname)
                                            if sname:
                                                ms_list.append({
                                                    "id": sname,
                                                    "name": cur_title or sname,
                                                    "enable": True,
                                                    "input": [line],
                                                    "output": [line]
                                                })
                                            cur_title = ""
                                    if ms_list:
                                        fetched_cfg = {"http_port": rport, "make_stream": ms_list}
                                        break
                    except Exception:
                        pass

            if isinstance(fetched_cfg, dict):
                self.cluster_cache[host_port] = fetched_cfg
                scount = len(fetched_cfg.get("make_stream", []) or [])
                total_remote_streams += scount
                synced_nodes += 1
                self.cluster_node_status[host_port] = {
                    "online": True,
                    "streams_count": scount,
                    "last_sync": int(time.time()),
                    "cached": False,
                    "error": ""
                }
            else:
                cached = self.cluster_cache.get(host_port)
                scount = len(cached.get("make_stream", []) or []) if isinstance(cached, dict) else 0
                self.cluster_node_status[host_port] = {
                    "online": False,
                    "streams_count": scount,
                    "last_sync": self.cluster_node_status.get(host_port, {}).get("last_sync", 0),
                    "cached": bool(cached),
                    "error": last_err
                }
                errors.append(f"{host_port}: {last_err}" + (" (используется кэш)" if cached else ""))

        self._apply_cluster_cache_to_streams()
        await self.apply_streams()
        return {"synced_nodes": synced_nodes, "total_streams": total_remote_streams, "errors": errors}

    async def sync_cluster_sources(self) -> dict:
        srv_res = await self._sync_cluster_servers()
        sources = self.config_data.get("cluster_sources", [])
        ckey = self.config_data.get("cluster_key", "")
        imported_count = srv_res.get("total_streams", 0)
        errors = list(srv_res.get("errors", []))
        if not sources or not self.http_client:
            return {"imported": imported_count, "errors": errors}

        existing_map = {s["name"]: s for s in self.config_data.get("streams", [])}
        for src in sources:
            raw_host = src.get("host", "").strip()
            if not raw_host:
                continue
            proto_pref = src.get("proto", "hls").strip()
            only_patterns = [p.strip() for p in src.get("only", "").split() if p.strip()]
            except_patterns = [p.strip() for p in src.get("except", "").split() if p.strip()]

            auth_header = {"User-Agent": "Mozilla/5.0"}
            clean_host = raw_host.replace("http://", "").replace("https://", "").rstrip("/")
            if "@" in clean_host:
                creds, clean_host = clean_host.split("@", 1)
                b64 = base64.b64encode(creds.encode("utf-8")).decode("ascii")
                auth_header["Authorization"] = f"Basic {b64}"
            if ckey:
                auth_header["X-Cluster-Key"] = ckey

            remote_streams = []
            fetched = False
            last_status = "нет ответа"
            endpoints = [
                f"http://{clean_host}/streamer/api/v3/streams?limit=2000&select=name,title",
                f"http://{clean_host}/api/v3/cluster/streams",
                f"http://{clean_host}/flussonic/api/media",
                f"http://{clean_host}/playlist.m3u8",
                f"http://{clean_host}/playlist.m3u"
            ]
            for ep in endpoints:
                try:
                    async with self.http_client.get(ep, headers=auth_header) as resp:
                        last_status = f"HTTP {resp.status}"
                        if resp.status != 200:
                            continue
                        text_body = await resp.text()
                        if text_body.lstrip().startswith("#EXTM3U"):
                            cur_title = ""
                            for line in text_body.splitlines():
                                line = line.strip()
                                if line.startswith("#EXTINF:"):
                                    cur_title = line.split(",", 1)[-1].strip()
                                elif line.startswith(("http://", "https://")):
                                    parts = line.split("/")
                                    sname = parts[-2] if line.endswith((".m3u8", "/mpegts")) and len(parts) >= 2 else parts[-1]
                                    sname = re.sub(r"[^a-zA-Z0-9_\-]", "", sname)
                                    if sname:
                                        remote_streams.append({"name": sname, "title": cur_title or sname, "direct_url": line})
                                    cur_title = ""
                            if remote_streams:
                                fetched = True
                                break
                        else:
                            j = json.loads(text_body)
                            if isinstance(j, dict) and "streams" in j and len(j["streams"]) > 0:
                                remote_streams = j["streams"]
                                fetched = True
                                break
                            elif isinstance(j, dict) and "streams" in j:
                                last_status = "0 потоков (доступ ограничен правами аккаунта)"
                except Exception as e:
                    last_status = str(e)[:50]

            if not fetched:
                errors.append(f"{clean_host}: {last_status}")
                continue

            for rs in remote_streams:
                if not isinstance(rs, dict):
                    continue
                rname = str(rs.get("name", "")).strip()
                rname_clean = re.sub(r"[^a-zA-Z0-9_\-]", "_", rname)
                if not rname_clean:
                    continue
                if any(fnmatch.fnmatch(rname_clean, pat) for pat in except_patterns):
                    continue
                if only_patterns:
                    if not any(fnmatch.fnmatch(rname_clean, pat) for pat in only_patterns):
                        continue
                    target_mode = "stream"
                else:
                    target_mode = "ondemand"

                rtitle = rs.get("title") or rname
                if rs.get("direct_url"):
                    stream_url = rs["direct_url"]
                elif proto_pref == "mpegts":
                    stream_url = f"http://{clean_host}/{rname}/mpegts"
                else:
                    stream_url = f"http://{clean_host}/{rname}/index.m3u8"

                if rname_clean in existing_map:
                    if stream_url not in existing_map[rname_clean].get("inputs", []):
                        existing_map[rname_clean].setdefault("inputs", []).append(stream_url)
                        imported_count += 1
                else:
                    new_st = {
                        "name": rname_clean,
                        "title": str(rtitle),
                        "mode": target_mode,
                        "engine": "astrag",
                        "quality": "best",
                        "buffer_mode": "30s",
                        "user_agent": "",
                        "enabled": True,
                        "inputs": [stream_url],
                        "source_timeout": 30,
                        "clients_timeout": 45,
                        "dvr_hours": 0,
                        "pushes": [],
                        "token": "",
                        "on_play": ""
                    }
                    self.config_data.setdefault("streams", []).append(new_st)
                    existing_map[rname_clean] = new_st
                    imported_count += 1

        if imported_count > 0:
            self.save_configs()
            await self.apply_streams()
        return {"imported": imported_count, "errors": errors}

    async def _cluster_sync_loop(self):
        await asyncio.sleep(2)
        try:
            if self.config_data.get("servers"):
                await self._sync_cluster_servers()
            if self.config_data.get("cluster_sources"):
                await self.sync_cluster_sources()
        except Exception:
            pass
        while True:
            await asyncio.sleep(45)
            try:
                if self.config_data.get("servers"):
                    await self._sync_cluster_servers()
                if self.config_data.get("cluster_sources"):
                    await self.sync_cluster_sources()
            except Exception:
                pass

    async def _pulse_sampler_loop(self):
        while True:
            try:
                now = time.time()
                for sess in list(self.sessions.values()):
                    if getattr(sess, "core_id", None) is not None and not sess.kicked:
                        sess.last_seen = now
                        w_s = self.workers.get(sess.stream_name)
                        if w_s:
                            w_s.touch_client()
                            if w_s.bitrate_in_kbps > 0:
                                sess.bytes_sent += int((w_s.bitrate_in_kbps * 1000 / 8.0) * 2.0)

                expired = [k for k, v in self.sessions.items() if now - v.last_seen > 25]
                for k in expired:
                    self.sessions.pop(k, None)
                
                client_counts = {}
                for sess in self.sessions.values():
                    if not sess.kicked and (now - sess.last_seen) < 15:
                        client_counts[sess.stream_name] = client_counts.get(sess.stream_name, 0) + 1
                self.active_clients_map = client_counts

                net = psutil.net_io_counters()
                dt = max(0.5, now - self._last_net_ts)
                rx_mbps = round(((net.bytes_recv - self._last_net_io.bytes_recv) * 8.0) / dt / 1_000_000.0, 2)
                tx_mbps = round(((net.bytes_sent - self._last_net_io.bytes_sent) * 8.0) / dt / 1_000_000.0, 2)
                self._last_net_io = net
                self._last_net_ts = now
                self.nic_in_mbps = max(0.0, rx_mbps)
                self.nic_out_mbps = max(0.0, tx_mbps)

                self.cached_cpu = round(psutil.cpu_percent(interval=None), 1)
                self.cached_ram = round(psutil.virtual_memory().percent, 1)
                shm_bytes = 0
                if RAM_ROOT.exists():
                    try:
                        for sub in os.scandir(RAM_ROOT):
                            if sub.is_dir(follow_symlinks=False):
                                for f_ent in os.scandir(sub.path):
                                    if f_ent.is_file(follow_symlinks=False):
                                        try:
                                            shm_bytes += f_ent.stat().st_size
                                        except OSError:
                                            pass
                    except OSError:
                        pass
                self.cached_shm_mb = round(shm_bytes / (1024 * 1024), 1)
                disk_dvr = psutil.disk_usage(str(DVR_ROOT))
                self.cached_dvr_percent = disk_dvr.percent
                self.cached_dvr_free_gb = round(disk_dvr.free / (1024 ** 3), 2)

                self.pulse_history.append({
                    "ts": time.strftime("%H:%M:%S"),
                    "in_mbps": self.nic_in_mbps,
                    "out_mbps": self.nic_out_mbps,
                    "cpu": self.cached_cpu,
                    "ram": self.cached_ram,
                    "shm_mb": self.cached_shm_mb
                })
                if len(self.pulse_history) > 60:
                    self.pulse_history = self.pulse_history[-60:]
            except Exception:
                pass
            await asyncio.sleep(2.0)

    def _cleanup_dvr_sync(self):
        now = time.time()
        for name, w in list(self.workers.items()):
            hours = int(w.cfg.get("dvr_hours", 0))
            s_dir = DVR_ROOT / name
            if not s_dir.exists() or hours <= 0:
                continue
            cutoff = now - (hours * 3600)
            cutoff_day = time.strftime("%Y-%m-%d", time.gmtime(cutoff))
            for day_dir in s_dir.iterdir():
                if not day_dir.is_dir():
                    continue
                if day_dir.name < cutoff_day:
                    shutil.rmtree(day_dir, ignore_errors=True)
                elif day_dir.name == cutoff_day:
                    for entry in os.scandir(day_dir):
                        if entry.name.endswith(".ts"):
                            try:
                                if int(entry.name.split("_")[0]) < cutoff:
                                    os.unlink(entry.path)
                            except Exception:
                                pass
        disk_limit = int(self.config_data.get("dvr_disk_limit", 85))
        if psutil.disk_usage(str(DVR_ROOT)).percent >= disk_limit:
            day_dirs = sorted(
                (d for s in DVR_ROOT.iterdir() if s.is_dir() for d in s.iterdir() if d.is_dir()),
                key=lambda p: p.name
            )
            if day_dirs:
                shutil.rmtree(day_dirs[0], ignore_errors=True)

    async def _dvr_cleaner_loop(self):
        while True:
            try:
                await asyncio.to_thread(self._cleanup_dvr_sync)
            except Exception:
                pass
            await asyncio.sleep(60)


MANAGER = StreamManager()


def render_with_prefs(html_template: str) -> str:
    t = str(MANAGER.config_data.get("ui_theme", "2"))
    l = str(MANAGER.config_data.get("ui_lang", "ru"))
    return html_template.replace("__DEFAULT_THEME__", t).replace("__DEFAULT_LANG__", l)


@web.middleware
async def admin_auth_middleware(req: web.Request, handler):
    if req.method == "OPTIONS":
        return web.Response(status=200, headers={
            "Access-Control-Allow-Origin": "*",
            "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS, HEAD",
            "Access-Control-Allow-Headers": "*"
        })
    path = req.path
    if path in ("/control", "/control/"):
        return await handler(req)
    if path == "/" or path.startswith("/api/"):
        if path in ("/api/v3/login", "/api/v3/logout", "/api/v3/ui_prefs", "/api/v3/cluster/streams"):
            return await handler(req)
        if not MANAGER.is_admin_authenticated(req):
            if path == "/":
                return web.Response(text=render_with_prefs(LOGIN_HTML), content_type="text/html")
            raise web.HTTPUnauthorized(text="StreamFlow Aria authentication required")
    return await handler(req)


async def ensure_ondemand_ready(w: StreamWorker, for_hls: bool = True) -> bool:
    w.touch_client()
    if w.cfg.get("engine") == "astrag" and isinstance(w.astrag_engine, CoreEngine) and CORE is not None:
        CORE.send("WAKE", w.name)
    m3u8 = w.ram_dir / "index.m3u8"
    for _ in range(250):
        if w.cfg.get("engine") == "astrag" and w.astrag_engine is not None:
            eng = w.astrag_engine
            if isinstance(eng, CoreEngine):
                return True
            if for_hls:
                eng._last_hls_access = time.monotonic()
            w._update_astrag_state()
            segs_dict = getattr(eng, "_segments", {})
            elapsed_eng = time.monotonic() - getattr(eng, "_created", time.monotonic())
            if for_hls:
                if len(segs_dict) >= 2:
                    return True
                if len(segs_dict) >= 1 and elapsed_eng >= 1.8:
                    return True
                if (not getattr(eng, "_seen_video_keyframes", False) and
                        int(getattr(eng, "_counts", {}).get("packets", 0)) >= 64 and
                        len(getattr(eng, "_current", b"")) >= 188 * 32 and
                        elapsed_eng >= 1.5):
                    try:
                        eng._finish_segment()
                        w._update_astrag_state()
                    except Exception:
                        pass
                    if len(getattr(eng, "_segments", {})) >= 1:
                        return True
            else:
                if len(segs_dict) >= 1 or (getattr(eng, "_current_has_keyframe", False) and len(getattr(eng, "_current", b"")) >= 188 * 64):
                    return True
                if int(getattr(eng, "_counts", {}).get("packets", 0)) >= 180 and elapsed_eng >= 1.0:
                    return True
        if m3u8.exists():
            segs = list(w.ram_dir.glob("seg_*.ts"))
            if len(segs) >= (2 if for_hls else 1):
                return True
        await asyncio.sleep(0.02)
    if w.cfg.get("engine") == "astrag" and w.astrag_engine is not None:
        if isinstance(w.astrag_engine, CoreEngine):
            return True
        return len(getattr(w.astrag_engine, "_segments", {})) >= 1 if for_hls else (int(getattr(w.astrag_engine, "_counts", {}).get("packets", 0)) >= 16)
    return m3u8.exists()


def _resolve_req_stream_name(req: web.Request) -> str:
    raw_name = req.match_info.get("name", "")
    srv_key = req.match_info.get("server_key", "")
    if srv_key:
        cand = f"cluster/{srv_key}/{raw_name}"
        resolved = MANAGER.resolve_stream_name(cand)
        if resolved in MANAGER.workers:
            return resolved
    return MANAGER.resolve_stream_name(raw_name)


async def handle_live_hls(req: web.Request) -> web.Response:
    name = _resolve_req_stream_name(req)
    w = MANAGER.workers.get(name)
    if not w or not w.cfg.get("enabled", True):
        raise web.HTTPNotFound(text="Stream not found or disabled")
    if not await MANAGER.check_auth(name, req):
        raise web.HTTPForbidden(text="Auth failed")

    sess = MANAGER.register_session(name, req, "HLS")
    if sess.kicked:
        raise web.HTTPForbidden(text="Session kicked")

    if w.cfg.get("engine") == "astrag" and w.astrag_engine is not None:
        eng = w.astrag_engine
        if isinstance(eng, CoreEngine) and _via_core(req):
            w.touch_client()
            if CORE is not None:
                CORE.send("WAKE", name)
            token_q = f"?token={req.query['token']}" if "token" in req.query else ""
            return _core_handoff(req, "hls", name, "", token_q, req.method)
        eng._last_hls_access = time.monotonic()
    ready = await ensure_ondemand_ready(w, for_hls=True)
    if w.cfg.get("engine") == "astrag" and w.astrag_engine is not None:
        eng = w.astrag_engine
        if isinstance(eng, CoreEngine):
            raise web.HTTPServiceUnavailable(text="Media is served through the public port only")
        await eng.wait_for_hls(timeout=3.0)
        w._update_astrag_state()
        content = eng.hls_playlist()
        if not content or "#EXTINF:" not in content:
            raise web.HTTPServiceUnavailable(text=f"Stream buffering ({w.codec_info})")
        token_q = f"?token={req.query['token']}" if "token" in req.query else ""
        if token_q:
            content = content.replace(".ts\n", f".ts{token_q}\n")
        raw_bytes = content.encode("utf-8")
        sess.bytes_sent += len(raw_bytes)
        return web.Response(
            body=raw_bytes,
            content_type="application/vnd.apple.mpegurl",
            headers={"Access-Control-Allow-Origin": "*", "Cache-Control": "no-cache"}
        )

    m3u8_file = w.ram_dir / "index.m3u8"
    if not ready or not m3u8_file.exists():
        raise web.HTTPServiceUnavailable(text=f"Stream buffering ({w.codec_info})")

    content = m3u8_file.read_text(encoding="utf-8", errors="ignore")
    token_q = f"?token={req.query['token']}" if "token" in req.query else ""
    if token_q:
        content = content.replace(".ts\n", f".ts{token_q}\n")

    raw_bytes = content.encode("utf-8")
    sess.bytes_sent += len(raw_bytes)
    return web.Response(
        body=raw_bytes,
        content_type="application/vnd.apple.mpegurl",
        headers={"Access-Control-Allow-Origin": "*", "Cache-Control": "no-cache"}
    )


async def handle_ram_media_chunk(req: web.Request) -> web.StreamResponse:
    name = _resolve_req_stream_name(req)
    seg_name = req.match_info["seg"]
    w = MANAGER.workers.get(name)
    if not w or "/" in seg_name or "\\" in seg_name or ".." in seg_name:
        raise web.HTTPNotFound()
    w.touch_client()
    if w.cfg.get("engine") == "astrag" and w.astrag_engine is not None:
        eng = w.astrag_engine
        if isinstance(eng, CoreEngine) and _via_core(req):
            est_bytes = max(262144, int((w.bitrate_in_kbps * 1000 / 8.0) * eng.seg_dur)) if w.bitrate_in_kbps > 0 else 524288
            sess = MANAGER.register_session(name, req, "HLS", est_bytes)
            if sess.kicked:
                raise web.HTTPForbidden()
            return _core_handoff(req, "seg", name, seg_name, "", req.method)
        m_seq = re.search(r"(\d+)\.ts$", seg_name)
        if m_seq:
            raw_seg = eng.get_segment(int(m_seq.group(1)))
            if raw_seg is not None:
                sess = MANAGER.register_session(name, req, "HLS", len(raw_seg))
                if sess.kicked:
                    raise web.HTTPForbidden()
                return web.Response(
                    body=raw_seg,
                    headers={"Content-Type": "video/mp2t", "Access-Control-Allow-Origin": "*", "Cache-Control": "max-age=30"}
                )
        raise web.HTTPNotFound()
    seg_path = w.ram_dir / seg_name
    try:
        file_size = seg_path.stat().st_size
    except FileNotFoundError:
        raise web.HTTPNotFound()
    sess = MANAGER.register_session(name, req, "HLS", file_size)
    if sess.kicked:
        raise web.HTTPForbidden()
    ctype = "video/mp4" if seg_name.endswith(".mp4") else "video/mp2t"
    return web.FileResponse(
        seg_path,
        headers={"Content-Type": ctype, "Access-Control-Allow-Origin": "*", "Cache-Control": "max-age=30"}
    )


async def handle_http_mpegts(req: web.Request) -> web.StreamResponse:
    name = _resolve_req_stream_name(req)
    w = MANAGER.workers.get(name)
    if not w or not w.cfg.get("enabled", True):
        raise web.HTTPNotFound(text="Stream not found")
    if not await MANAGER.check_auth(name, req):
        raise web.HTTPForbidden(text="Auth failed")

    if w.cfg.get("engine") == "astrag" and isinstance(w.astrag_engine, CoreEngine) and _via_core(req):
        w.touch_client()
        if CORE is not None:
            CORE.send("WAKE", name)
        if req.method == "HEAD":
            return web.Response(
                body=b"",
                headers={
                    "Content-Type": "video/mp2t",
                    "Cache-Control": "no-store",
                    "Accept-Ranges": "none",
                    "Access-Control-Allow-Origin": "*",
                }
            )
        return _core_handoff(req, "ts", name, "")

    ready = await ensure_ondemand_ready(w, for_hls=False)
    if not ready and not (w.cfg.get("engine") == "astrag" and w.astrag_engine is not None):
        raise web.HTTPServiceUnavailable(text="Stream offline")

    resp = web.StreamResponse(
        status=200,
        reason="OK",
        headers={
            "Content-Type": "video/mp2t",
            "Access-Control-Allow-Origin": "*",
            "Cache-Control": "no-cache",
            "Connection": "keep-alive"
        }
    )
    await resp.prepare(req)
    if req.transport is not None:
        cli_sock = req.transport.get_extra_info("socket")
        if cli_sock is not None:
            try:
                cli_sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                cli_sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
            except OSError:
                pass
    sess = MANAGER.register_session(name, req, "MPEG-TS")
    if w.cfg.get("engine") == "astrag" and w.astrag_engine is not None:
        eng = w.astrag_engine
        if hasattr(eng, "subscribe_with_prebuffer"):
            queue, prebuffer_parts = eng.subscribe_with_prebuffer(512, chunk_mode=True)
        else:
            prebuffer_parts = eng.get_mpegts_prebuffer_parts()
            queue = eng.subscribe(512, chunk_mode=True)
        try:
            burst_sent = False
            aligned = False
            if prebuffer_parts:
                for part in prebuffer_parts:
                    mv_p = memoryview(part)
                    try:
                        for off in range(0, len(part), 65424):
                            if sess.kicked or not w.cfg.get("enabled", True):
                                break
                            chunk_pb = bytes(mv_p[off:off + 65424])
                            await asyncio.wait_for(resp.write(chunk_pb), timeout=12.0)
                            sess.bytes_sent += len(chunk_pb)
                    finally:
                        mv_p.release()
                sess.last_seen = time.time()
                prebuffer_parts.clear()
                aligned = True
                burst_sent = True
            align_deadline = time.monotonic() + 2.0
            align_packets = 0
            max_align_packets = 12000
            while not sess.kicked and w.cfg.get("enabled", True) and w.astrag_engine is eng:
                w.touch_client()
                pkt = await asyncio.wait_for(queue.get(), timeout=15.0)
                try:
                    queue.task_done()
                except ValueError:
                    pass
                if pkt is None:
                    break
                if not aligned:
                    align_packets += 1
                    has_video = any(t == "VIDEO" for t in getattr(eng, "_elementary_pids", {}).values())
                    if (not has_video and align_packets >= 16) or eng.is_video_keyframe_packet(pkt) or time.monotonic() >= align_deadline or align_packets >= max_align_packets:
                        aligned = True
                        burst = eng.bootstrap_burst()
                        out_start = bytes(burst + pkt) if burst else bytes(pkt)
                        await asyncio.wait_for(resp.write(out_start), timeout=12.0)
                        sess.bytes_sent += len(out_start)
                        burst_sent = True
                    continue
                if not burst_sent:
                    burst = eng.bootstrap_burst()
                    if burst:
                        await asyncio.wait_for(resp.write(burst), timeout=12.0)
                        sess.bytes_sent += len(burst)
                    burst_sent = True
                if queue.empty() and isinstance(pkt, (bytes, bytearray)):
                    await asyncio.wait_for(resp.write(pkt), timeout=12.0)
                    sess.bytes_sent += len(pkt)
                    sess.last_seen = time.time()
                    continue
                buf = bytearray(pkt)
                while len(buf) + 188 <= 65424 and not queue.empty():
                    nxt = queue.get_nowait()
                    try:
                        queue.task_done()
                    except ValueError:
                        pass
                    if nxt is None:
                        break
                    buf.extend(nxt)
                await asyncio.wait_for(resp.write(buf), timeout=12.0)
                sess.bytes_sent += len(buf)
                sess.last_seen = time.time()
        except Exception:
            pass
        finally:
            eng.unsubscribe(queue)
            MANAGER.sessions.pop(sess.id, None)
        return resp
    sent_history = set()

    keep_segs = 2
    try:
        f_list = [f for f in os.listdir(w.ram_dir) if f.startswith("seg_") and f.endswith(".ts")]
    except OSError:
        f_list = []
    f_list.sort()
    if len(f_list) > keep_segs:
        for old_s in f_list[:-keep_segs]:
            sent_history.add(old_s)

    last_seq_num = -1
    first_seg_burst = True
    m3u8_path = w.ram_dir / "index.m3u8"
    try:
        while not sess.kicked and w.cfg.get("enabled", True):
            w.touch_client()
            segs = sorted(w.ram_dir.glob("seg_*.ts"), key=lambda p: p.name)
            pending_segs = [s for s in segs if s.name not in sent_history]
            extinf_map = {}
            if pending_segs and m3u8_path.exists():
                try:
                    m_lines = m3u8_path.read_text(encoding="utf-8", errors="ignore").splitlines()
                    cur_dur = float(HLS_SEG_TIME)
                    for ml in m_lines:
                        ml = ml.strip()
                        if ml.startswith("#EXTINF:"):
                            try:
                                cur_dur = max(0.5, float(ml[8:].split(",", 1)[0]))
                            except ValueError:
                                cur_dur = float(HLS_SEG_TIME)
                        elif ml and not ml.startswith("#"):
                            extinf_map[ml.split("?", 1)[0].strip()] = cur_dur
                except Exception:
                    pass
            sent_any = False
            for idx_s, s in enumerate(pending_segs):
                try:
                    seq_num = int(s.stem.split("_")[1])
                except Exception:
                    seq_num = last_seq_num + 1
                if last_seq_num != -1 and seq_num <= last_seq_num and (last_seq_num - seq_num) < 500:
                    sent_history.add(s.name)
                    continue
                sent_history.add(s.name)
                last_seq_num = seq_num
                is_latest = (idx_s == len(pending_segs) - 1)
                try:
                    fsize = max(1, s.stat().st_size)
                    actual_dur = extinf_map.get(s.name, float(HLS_SEG_TIME))
                    seg_bps = fsize / actual_dur
                    seg_clock = time.monotonic()
                    with open(s, "rb") as f:
                        while not sess.kicked and w.cfg.get("enabled", True):
                            chunk = f.read(65424 if not first_seg_burst else 261696)
                            if not chunk:
                                break
                            await resp.write(chunk)
                            sess.bytes_sent += len(chunk)
                            sess.last_seen = time.time()
                            if first_seg_burst:
                                first_seg_burst = False
                                continue
                            if is_latest and seg_bps > 0:
                                slice_dur = (len(chunk) / seg_bps) * 0.92
                                seg_clock += slice_dur
                                wait = seg_clock - time.monotonic()
                                if wait > 0.005:
                                    await asyncio.sleep(min(wait, 0.08))
                    sent_any = True
                except Exception:
                    break
            if len(sent_history) > 200:
                sent_history = set(sorted(sent_history)[-100:])
            await asyncio.sleep(0.08 if not sent_any else 0.01)
    except Exception:
        pass
    finally:
        MANAGER.sessions.pop(sess.id, None)
    return resp


async def handle_play_entry(req: web.Request) -> web.StreamResponse:
    raw_name = req.match_info.get("name", "")
    if raw_name.endswith(".m3u8"):
        req.match_info["name"] = raw_name[:-5]
        return await handle_live_hls(req)
    if raw_name.endswith(".ts"):
        req.match_info["name"] = raw_name[:-3]
        return await handle_http_mpegts(req)
    fmt = req.query.get("format", "").lower()
    if fmt == "hls":
        return await handle_live_hls(req)
    return await handle_http_mpegts(req)


async def handle_control_api(req: web.Request) -> web.Response:
    ckey = MANAGER.config_data.get("cluster_key", "")
    req_key = req.headers.get("X-Cluster-Key") or req.query.get("cluster_key", "")
    if not MANAGER.is_admin_authenticated(req):
        if not (ckey and req_key == ckey):
            raise web.HTTPUnauthorized(text="Authentication required")
    try:
        body = await req.json()
    except Exception:
        body = {}
    cmd = str(body.get("cmd") or "load").strip().lower()
    if cmd == "load":
        ms_list = []
        for s in MANAGER.config_data.get("streams", []):
            if s.get("_cluster_host"):
                continue
            sid = s.get("name", "")
            if not sid:
                continue
            auto_in = set(s.get("_cluster_auto_inputs") or [])
            clean_inputs = [u for u in s.get("inputs", []) if u not in auto_in]
            ms_list.append({
                "id": sid,
                "name": s.get("title") or sid,
                "enable": bool(s.get("enabled", True)),
                "input": clean_inputs,
                "output": s.get("pushes", []),
                "token": str(s.get("token", "")),
                "audio_track": str(s.get("audio_track", "0")),
            })
        hport = MANAGER.config_data.get("http_port", 8080)
        return web.json_response({
            "http_port": hport,
            "settings": {
                "http_play_stream": True,
                "http_play_hls": True,
                "http_play_port": hport,
            },
            "make_stream": ms_list,
            "servers": MANAGER.config_data.get("servers", []),
        }, headers={"Access-Control-Allow-Origin": "*"})
    if cmd == "status":
        st_map = {}
        for name, w in MANAGER.workers.items():
            st_map[name] = {
                "onair": w.status == "Online",
                "bitrate": w.bitrate_in_kbps,
                "clients": w.active_clients_count(),
                "status": w.status
            }
        return web.json_response({"status": st_map}, headers={"Access-Control-Allow-Origin": "*"})
    if cmd == "set-servers":
        if isinstance(body.get("servers"), list):
            MANAGER.config_data["servers"] = body["servers"]
            MANAGER.save_configs()
            await MANAGER._sync_cluster_servers()
        return web.json_response({"status": "ok"}, headers={"Access-Control-Allow-Origin": "*"})
    return web.json_response({"status": "ok"}, headers={"Access-Control-Allow-Origin": "*"})


def _find_dvr_segments_in_range(s_dir: Path, start_ts: int, end_ts: int) -> list:
    matched = []
    cur_day_ts = start_ts - (start_ts % 86400)
    while cur_day_ts <= end_ts:
        day_str = time.strftime("%Y-%m-%d", time.gmtime(cur_day_ts))
        day_dir = s_dir / day_str
        if day_dir.is_dir():
            try:
                for entry in os.scandir(day_dir):
                    if entry.name.endswith(".ts"):
                        try:
                            ts_val = int(entry.name.split("_")[0])
                            if start_ts <= ts_val <= end_ts:
                                matched.append((ts_val, f"{day_str}/{entry.name}"))
                        except ValueError:
                            pass
            except OSError:
                pass
        cur_day_ts += 86400
    matched.sort(key=lambda x: x[0])
    return matched


async def handle_dvr_catchup_m3u8(req: web.Request) -> web.Response:
    name = MANAGER.resolve_stream_name(req.match_info["name"])
    start_ts = int(req.match_info["start"])
    duration_raw = req.match_info["duration"]
    w = MANAGER.workers.get(name)
    if not w:
        raise web.HTTPNotFound()
    if not await MANAGER.check_auth(name, req):
        raise web.HTTPForbidden()

    end_ts = int(time.time()) if duration_raw == "now" else (start_ts + int(duration_raw))
    s_dir = DVR_ROOT / name
    if not s_dir.exists():
        raise web.HTTPNotFound(text="DVR archive empty")

    matched = await asyncio.to_thread(_find_dvr_segments_in_range, s_dir, start_ts, end_ts)
    if not matched:
        raise web.HTTPNotFound(text="No DVR segments in requested range")

    lines = ["#EXTM3U", "#EXT-X-VERSION:3", "#EXT-X-TARGETDURATION:5", f"#EXT-X-MEDIA-SEQUENCE:{matched[0][0]}"]
    if duration_raw != "now":
        lines.append("#EXT-X-PLAYLIST-TYPE:VOD")
    for _, rel_posix in matched:
        lines.append(f"#EXTINF:{HLS_SEG_TIME}.000,")
        lines.append(f"/dvr_file/{name}/{rel_posix}")
    if duration_raw != "now":
        lines.append("#EXT-X-ENDLIST")

    body = "\n".join(lines).encode("utf-8")
    MANAGER.register_session(name, req, "DVR-HLS", len(body))
    return web.Response(body=body, content_type="application/vnd.apple.mpegurl", headers={"Access-Control-Allow-Origin": "*"})


async def handle_timeshift_m3u8(req: web.Request) -> web.Response:
    name = MANAGER.resolve_stream_name(req.match_info["name"])
    offset = int(req.match_info["offset"])
    target_ts = int(time.time()) - offset
    s_dir = DVR_ROOT / name
    if not s_dir.exists():
        raise web.HTTPNotFound()

    matched = await asyncio.to_thread(_find_dvr_segments_in_range, s_dir, target_ts - 16, target_ts + 16)
    if not matched:
        raise web.HTTPNotFound(text="Timeshift window not found")

    lines = ["#EXTM3U", "#EXT-X-VERSION:3", "#EXT-X-TARGETDURATION:5", f"#EXT-X-MEDIA-SEQUENCE:{matched[0][0]}"]
    for _, rel_posix in matched[-15:]:
        lines.append(f"#EXTINF:{HLS_SEG_TIME}.000,")
        lines.append(f"/dvr_file/{name}/{rel_posix}")

    body = "\n".join(lines).encode("utf-8")
    MANAGER.register_session(name, req, "TIMESHIFT", len(body))
    return web.Response(body=body, content_type="application/vnd.apple.mpegurl", headers={"Access-Control-Allow-Origin": "*"})


async def handle_dvr_segment_file(req: web.Request) -> web.StreamResponse:
    name = MANAGER.resolve_stream_name(req.match_info["name"])
    rel = req.match_info["rel"]
    if ".." in rel or rel.startswith("/"):
        raise web.HTTPNotFound()
    target = DVR_ROOT / name / rel
    try:
        file_size = target.stat().st_size
    except FileNotFoundError:
        raise web.HTTPNotFound()
    MANAGER.register_session(name, req, "DVR-HLS", file_size)
    return web.FileResponse(target, headers={"Content-Type": "video/mp2t", "Access-Control-Allow-Origin": "*"})


async def handle_embed_html(req: web.Request) -> web.Response:
    name = MANAGER.resolve_stream_name(req.match_info["name"])
    token_q = f"?token={req.query['token']}" if "token" in req.query else ""
    html = f"""<!DOCTYPE html><html><head><meta charset="utf-8"><title>StreamFlow Aria - {name}</title>
    <script src="https://cdn.jsdelivr.net/npm/hls.js@latest"></script>
